INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('d32f7fc6-1381-45d0-a39c-536695bea21c'::uuid, 'b37a2a0b-5122-49b0-98d9-13b0b8ca2061'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'juara karate kategori kumite', 'kesulitan di MTK, nilai tinggi di olah raga', 'dukungan untuk di ingatkan sholat, dan hafalan di juz 30 ', 'lebih dekat sama ibnunya, ', 'semuanya bisa mengikuti pelajaran', 'Terima', true, '2026-05-09 02:54:56.377'::timestamptz, '2026-05-09 02:54:56.377'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('7dd8cddf-9bfc-4e42-b240-8f894ef22586'::uuid, '9226a3db-81a9-4a25-857f-0a634ad03d34'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'anak ke-1 dari 2 bersaudara, disiplin dan tanggung jawabnya masih harus ditingkatkan.', 'IPA & Bahasa kurang suka, math yang dia suka & nilainya bagus', 'jika ada kegiatan sekolah, orang tua mendukung, boleh menginap jika ada kegiatan sanlat, camp.', 'anaknya mau berusaha kalau punya keinginan.', 'Tidak punya alergi makanan atau obat tertentu. Harapannya si anak lebih terkontrol, dan lebih baik dari sebelumnya. Tau Al Fakhir dari tetangga.', 'Terima', true, '2026-05-09 03:02:44.348'::timestamptz, '2026-05-09 03:02:44.348'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('0d855bf2-b428-4dce-82e0-8350ddd95097'::uuid, '80fca573-b109-4a19-9047-f863617d23d5'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'pemberian reward apabila berhasil melakuakn sesuatu', 'pelajaran yang di sukai dan cepat danggap dan eksrovet, bahasa arab, SKI, bahasa inggris, dan MTK agak kurang dan semuanya tidak ada masalh', 'tidak ada targetan dari orang tua hanya memberikan seluas-luasnya kepada anaknya', 'tidak perlu ingatkan untuk ibadah sudah mandiri ', 'orangnya mudah bergaul dan pencetus, dan harapanya cita-citanya tercapai', 'Terima', true, '2026-05-09 03:04:04.184'::timestamptz, '2026-05-09 03:04:04.184'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('8595feb7-d106-475f-bc40-04803e68215e'::uuid, '40e820be-b3df-4720-aae0-160ec5311f46'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Zafran adalah tipe harus disuruh, sering lupa, tanggung jawabnya kurang, seperti barang yang sering hilang di sekolah.', 'unggul di math, les math & English dari tk. kekurangan di hafalan. Ikut Math Champ di Ruang Guru. Aktif di Archery. ', 'Ortu tidak suka kalau sekolah tidak menginfo kejadian yang dialami si anak.', 'Anaknya ekstrovert tapi ke sebagian orang saja. ', 'Sekolah tidak memberikan akses untuk ikut olimpiade. Guru juga tidak memfollow up saat  ada temannya yang jahil ke dia. Alergi dingin saja kalau pagi.', 'Terima', true, '2026-05-09 03:12:50.98'::timestamptz, '2026-05-09 03:12:50.98'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('d8542586-45bb-4d91-a5d9-213cc9e2717a'::uuid, 'ded7f787-2d41-433a-a127-a5d8a2224340'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'di harisekolah tidak mengguankan HP dan membiasakan ', 'nilai akademik IPA, komputer lebih menojol, dan nilai MTK agak kurang', 'mendukung penuh apa yang di lakukan oleh andnda ', 'perlu di ingatkan yang tadinya di sekolah biasa tapi ketika di rumah, juz ', 'harapan anak saya bisa mengikuti apa yang di telah di tetapkan dis sekolah, akhlaknya baik, tuturkatanya baik sehingga menjadi kebanggan orang tua, nusa dan agama', 'Terima', true, '2026-05-09 03:19:05.695'::timestamptz, '2026-05-09 03:19:05.695'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('6a31104a-20c4-4406-9517-c6550cce54c1'::uuid, '9dade648-5a4c-46b5-8ece-ac22e2a87805'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'kegiatan ananda lebih banyak diluar untuk sepak bola, mengaji, dan taekwondo. ', 'ananda sudah siap dalam akademik', 'keluarga support dalam setiap kegiatan, harapan orangtua pendidikan agama bisa seimbang, karena ibu seorang mualaf dan tidak bisa banyak mengajarkan ilmu agama', 'kontrol emosi bagus, kadang terlalu santai, sudah mandiri dan bisa bersosialisasi dengan baik walaupun di lingkungan baru', 'orangtua minta dispensasi ketika nanti ada pertandingan sepak bola, karena ananda sudah mengikuti club sepak bola yang besar dab sering turnamen di luar kota', 'Terima', true, '2026-05-09 03:22:48.632'::timestamptz, '2026-05-09 03:22:48.632'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('4e32ecd8-f8dd-4ad4-8a8e-345b2cb97dcb'::uuid, '3ae035bb-c1ae-4334-9677-00f9a8f06145'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Anak tunggal, kedua orang tua kerja, di rumah sendiri. Ada kelas ngaji sore di komplek. Anaknya akan gigih kalau ada maunya. Anaknya mandiri karena biasa sendiri.', 'kurang fokus karena aktif sekali. Walaupun pindahan, tapi bisa mengikuti. Masuk 5 besar. Kalau di pelajaran sering nanya, karena ragu akan kemampuannya.', 'Ayah Bunda selalu mendukung semua kegiatan sekolah. Ortu juga membatas penggunaan gadget.', 'anaknya supel banget, iseng sama temen2nya. Anaknya bosenan. Anaknya suka ngambek, agak egois kalau di rumah, tapi kalau di sekolah mau mengalah. Anaknya PD.', 'pindahan dari Purwakarta saat kelas 4 SD ke Pengasinan. Tahu Al Fakhir dari tetangga. Tidak ada alergi, tapi gampang sakit perut kalo minum yang aneh2. ', 'Terima', true, '2026-05-09 03:23:30.107'::timestamptz, '2026-05-09 03:23:30.107'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('962127e6-bec5-4d58-88a9-06171bca731e'::uuid, 'ac374288-1322-4e08-8e85-58c47891fbbe'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'untuk semuanya tidak ada masalah dan dapat mengikuti', 'akademik yang kurang di MTK, bahasa arab, bahasa inggris, akidah akhlaq dan al qur''an hadist', 'orang tua mendukung penuh apa yang di lakukan oleh ananda termasuk biaya', 'untuk pembiasaan ibadah sudah biasa melakukan pembiasan ibadah, dan kareketernya sudah terbangun dalam kedisiplinan', 'ada gangguan hiper aktif, dari riwayat ADHD dan sekarang sudah tidak ada masalah dan bisa mengikuti', 'Terima', true, '2026-05-09 03:29:55.392'::timestamptz, '2026-05-09 03:29:55.392'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('cee12186-0d87-4cb3-a77d-51050274fa25'::uuid, '3327e485-4b6d-450a-ac79-3b13902d3e65'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Sholatnya masih suka bolong-bolong. Ayahnya sudah meninggal tahun 2024.  Ibunya kerja., libur Sabtu Minggu. Ibunya PNS di Kemenkeu.', 'Al Qur''an hadits yang paling disuka. Anaknya males baca.', 'Orang tua mendukung semua kegiatan sekolah.', 'Anaknya baik, supel, sopan, gampang diatur. Anaknya suka futsal dan suka jadi perwakilan di kelas. ', 'Tahu Al Fakhir dari tetangga, Jilan. Mohon sekolah membuat aturan dan kontrol agar anak wajib sholat subuh,magrib, dan isya. Tidak ada alergi dan kendala sakit lain.', 'Terima', true, '2026-05-09 03:36:12.298'::timestamptz, '2026-05-09 03:36:12.298'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('45abfa8f-0867-4953-bdc9-84b99f38808c'::uuid, '9c71f848-1bda-4b67-89a8-d624b9cb90a5'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'sudah selesai juz 30 ', 'kesulitannya bahasa arab, unggul dan suka MTK, ', 'siap mendukung apa yang menjadi program sekolah', 'Sifat penurut di rumah, ibadahnya belum sepenuhnya di jalanin, ', 'haparapan terbesarnya ingin akhlaknya baik dan menjadi kebanggan keluarga', 'Terima', true, '2026-05-09 03:39:03.754'::timestamptz, '2026-05-09 03:39:03.754'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('99c9a45c-62d6-4c6d-af82-4e8bb1924609'::uuid, '7e025f84-a676-4a98-bc66-4a9b496a756b'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Secara umum tidak ada masalah.', 'Sukanya tahfidz, anaknya tidak tertarik bahasa Inggris & math.', 'Orang tua mendukung semua kegiatan sekolah. ', 'Anaknya introvert, diam, ga banyak omong, tapi tetep mau tampil di depan umum. Temannya terbatas, dan lebih nyaman. Kurang ekspresif. ', 'Tahu Al Fakhir dari tetangga. Ikut lomba tahfidz juara 2 di sekolah. Tidak ada alergi makanan dan obat.', 'Terima', true, '2026-05-09 03:48:50.162'::timestamptz, '2026-05-09 03:48:50.162'::timestamptz);
