INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('7aeecfda-e713-463a-982d-44fbeb6c6806'::uuid, '007717e5-4520-4db9-9c7a-c7f3b7d0721f'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'harapanya pingin sholeh, sukses, berhasil kepercayaan diri lebih baik, komunikasi lebih baik, tidak tertinggal bisa terbangun. ', 'tidak ada masalah, literasai dan numerasi, suka MTK, dan nilai tertinggi SBK ', 'tidak ada masalah untuk anak lebih mengikuti', 'masih perlu diingatkan, sikap masih perlu bantuan untuk beradaptasi', 'tidak ', 'Terima', true, '2026-05-23 01:52:48.293'::timestamptz, '2026-05-23 01:52:48.293'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('cffeab29-7a4f-4227-99b1-37d019e478a0'::uuid, '8a505330-5a54-47e2-a4d2-d26610e6b387'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'anaknya lebih baik bukan hanya akademik tapi juga ibadahnya dan sholehah ', 'tidak ada masalah dalam akemik, PKN dan PABP, Dan tidak di suka adalah MTK', 'tidak ada malah dengan kebijan sekolah', 'Tidak terlalu, untuk ibadah spertinya sholat, untuk subuhnya tidak maslalah , hafalan juz 30, ', 'tidak ada ', 'Terima', true, '2026-05-23 02:03:05.343'::timestamptz, '2026-05-23 02:03:05.343'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('fabe77e6-a9ce-4f9b-8a99-3f50fad91b52'::uuid, 'f4adb55c-5757-4a08-a0ce-21ab39d7d0f7'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'tampil di depan kurang percaya diri, akhlaq dan budi pekerti lebih baik lagi, sholatnya, dunia dan akhirat seimbang, sebelumnya tapi lihat dari medsos, lebih fokus fublic speaking ', 'bisa mengikuti, pelajaran bahasa inggris, faigon. MTK Kurang di minati', 'tidak ada masalah dan jangan dadakan', 'pembiasaan ibadahnya perlu di ingatkan, subuhnya perlu dingatakan, ', 'tidak ada', 'Terima', true, '2026-05-23 02:16:19.156'::timestamptz, '2026-05-23 02:16:19.156'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('f00bd585-22fb-46a1-b89e-c45498c3c1fd'::uuid, '43f0bed0-6a5c-4bc2-9485-3c3315ce89d1'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Anak ketiga, percaya diri sekali. Di TK perwakilan kelas untuk pidato. Basicnya TK Ilslam, sudah ada hafalan dan bahasa Arab sudah bisa sedikit-sedikit.', 'Toilet training aman, sudah bisa membaca dan berhitung.', 'Setiap kegiatan akan support ke ananda', 'Supel, cepet bosen kalau sendirian, cengeng karena anak bungsu. ', 'Juara Harapan 1 pidato tingkat kecamatan di Bogor. Bapaknya sangat vokal ya, kepala damkar di Jakarta Selatan, jadi harus siap-siap ya! :D', 'Terima', true, '2026-05-23 02:46:11.625'::timestamptz, '2026-05-23 02:46:11.625'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('7449250f-35a8-4728-974c-fc26af2f02d5'::uuid, 'cf42c3eb-85e4-4f97-9560-63085cc0920a'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Arifah Hilyati, S.S, M.Pd', 'Aldafi sudah mandiri, makan-minum sendiri.Sudah bisa membersihkan diri ketika di toilet. Sudah ada awareness- (membawa barang, membawa infaq). Tidak pernah tantrum meskipun kadang emosional.', 'Aldafi sudah bisa membaca dan menulis. Sudah lulus Tahsin metode Ummi. Butuh proses agak lama untuk Sholat. ', 'Dafi memang gampang emosi. Untuk meluapkan emosinya Aldafi bisa meredamnya dengan bercerita pada ayah dan bundanya. Komunikasi ayah bunda ada keterbukaan.', 'Sudah bisa  berteman, agak pemilih yang se frekuensi.', 'Hambatan belajar tidak ada.', 'Terima', true, '2026-05-23 02:47:11.2'::timestamptz, '2026-05-23 02:47:11.2'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('644ee6dc-e456-4547-953a-c3efe27b03fb'::uuid, '807a2c56-31e6-49b5-8087-a415b0edcfba'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Anak bungsu, di rumah tidak mau belajar, masih harus membantu menyiapkan semuanya.', 'Adha udah aman toilet training, udah ga ngompol. Mengaji masih di Iqro 3. Membacanya belum bisa, baru kenal huruf. ', 'SIap mendukungnya. ', 'Anaknya aktif, tapi pemalu kalau untuk tampil ke depan. Masih belum terlalu percaya diri, jadi harus didorong dulu. Awalnya ibunya harus nunggu di TK.', 'Jangan sekelas sama Zaidan, nanti bercanda dan berantem. Khawatir lari pulang ke rumah sebelum pulang ke rumah.', 'Terima', true, '2026-05-23 02:56:14.85'::timestamptz, '2026-05-23 02:56:14.85'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('f3942c2d-cdf1-4bdd-bee9-dededac519c0'::uuid, '58b847ed-dda5-4a13-920d-aab983cc7728'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Arifah Hilyati, S.S, M.Pd', 'Adiba sudah bisa makan-minum sendiri, pup dan cebok sendiri, mandi sendiri. Addict main HP.', 'Adiba belum lancar membaca, menulis masih terbalik- balik. Sudah kenal huruf. ', 'Komunikasi tidak berjalan dengan intense, ayah sibuk, ngobrol sebentar.', 'Dengan orang baru, Adiba malu-malu tapi lama-lama bisa bersosialisasi.', NULL, 'Terima', true, '2026-05-23 03:02:32.502'::timestamptz, '2026-05-23 03:02:32.502'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('101a64eb-2a31-4adc-8b31-2e3ab8d5c56d'::uuid, 'd338abc5-cdca-4c3c-809e-246b51437c12'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Anak pertama dari 2 bersaudara. Hafalan surat pendek sudah dibiasakan di TK. ', 'Toilet training aman. Calistung dasar udah bisa. ', 'siap mendukung berbagai kebijakan dan kegiatan yang diadakan di sekolah.', 'Anaknya pemalu di awal, tapi kalau udah panas, baru rame. Konsentrasinya gampang pecah, gampang terpengaruh teman, gampang lupa.', 'Tidak ada alergi dan semoga bisa lebih percaya sama kemampuannya. Pernah ikut lomba matematika, baca puisi. ', 'Terima', true, '2026-05-23 03:06:36.114'::timestamptz, '2026-05-23 03:06:36.114'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('58b3759c-bd63-44f6-a890-603d5d78de98'::uuid, '10cb2948-f458-4201-a335-22a6a7b052f2'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Arifah Hilyati, S.S, M.Pd', 'Maryam mandiri ke toilet sendiri. Makan dan minum mandiri. Terbiasa membantu orang tua. Maryam mau belajar ngepel.', 'Maryam bisa membaca belum lancar. Menulis sudah bisa. ', 'Orang tua sering quality time intense. Di sekolah , ananda lebih auditory. ', 'Emosinya cukup besar, teguh pada pendiriannya.', 'Moody. ', 'Terima', true, '2026-05-23 03:12:29.398'::timestamptz, '2026-05-23 03:12:29.398'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('897d75a2-2401-4ec3-865c-85a067a1e4c9'::uuid, '9e7ebc95-6804-4b26-a1f2-7d9f018c6d94'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'anak pertama, baru 1 anaknya. Terindikasi ASD dari Dokter Spesialis Anak, sosialisasinya agak bermasalah, komunikasinya kurang, kadang tidak paham percakapan teman.', 'Lebih cepat menangkap secara visual. Dari segi hafalan belum banyak, menulisnya belum sesuai ukuran normal, membaca lancar, berhitungnya sedikit-sedikit.', 'sudah terapi di umur 2-4 tahun. ketika TK berhenti terapi sampai sekarang.  ', 'Belajarnya belum bisa duduk diam, masih suka lari-larian. Fokusnya masih kurang, baru bisa berbicara kalimat sederhana saja, kalimat panjang belum bisa. Pemakaian kata-kata belum pas.', 'Kalau ada teman yang menangis, dia akan ikut menangis. Misalnya saat mendengar sesuatu yang aneh, dia akan tutup telinga. Ortu berharap tidak dengan shadow teacher, tapi jika hasil tes IQ menyarankan shadow, tidak masalah.', 'Pertimbangkan', true, '2026-05-23 03:22:06.341'::timestamptz, '2026-05-23 03:22:06.341'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('0aa63b46-ec8a-499b-8755-b1ace82560ec'::uuid, 'f5cf3f10-0359-45bf-bd3c-38693b4cc08a'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Arifah Hilyati, S.S, M.Pd', 'Sudah mandiri. pup dan pipis , cuci kaki dan tangan bisa sendiri. Makan dan minum sendiri agak berantakan. ', 'Sudah bisa membaca tapi belum lancar. Berhitung sampai 2 bilangan.', 'Bunda lebih banyak berkomunikasi dengan Keenan. ', 'Keenan anaknya sangat bemosional. tantrum. Sensitif. sangat penyayang, sangat peduli. empatinya tinggi sekali. jika Mami menagis dipeluk. Ananda aktif tapi masih suka ngambek, ', 'Oleh psikolog, diyatkan autisme yang positif. Keenan mengahafal surah. Kecenderungan suka dengan Art.', 'Terima', true, '2026-05-23 03:22:33.29'::timestamptz, '2026-05-23 03:22:33.29'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('4ae4a8c9-5aed-4c77-89b0-b78887f342ef'::uuid, '0b1ad581-4655-416e-80db-7a8b5bee0e37'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Anak pertama dari 2 bersaudara. Rumah di Cipayung. Tidak TK, hanya ikut Math Kids dan Rumah Belajar Calistung tidak formal.', 'Calistung sudah aman, Iqro sudah bisa. Toilet training sudah lulus, hanya dia biasa pakai toilet duduk yang tanpa washer.', 'Rumah masih pindah-pindah, sehingga anak sulit sekolah formal. Bapak Ibu akan mendukung setiap kegiatan sekolah.', 'Anaknya pemalu di awal, kurang PD. Anaknya kidal untuk menulis. Makan dan salim tetap dibiasakan untuk tangan kanan.', 'Tidak ada alergi, sempat 2x types dirawat, mungkin karena sering pindah-pindah rumah jadi daya tahan tubuhnya agak lemah. ', 'Pertimbangkan', true, '2026-05-23 03:32:03.33'::timestamptz, '2026-05-23 03:32:03.33'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('9807152c-3bfe-43d1-8234-7b4cecd0cdb4'::uuid, 'c11f634e-8a0a-4b05-b4cb-320e647ab90e'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Arifah Hilyati, S.S, M.Pd', 'Qisha sudah mandiri. makan  sendiri, mandi sendiri. Bisa cebok sendiri.', 'Sudah  mengenal huruf namun belum bisa membaca. Menulis belum lancar.', 'Komunikasi intense, terutama dengan mamanya. Sebulan sekali family quality. Qisha anak ketiga. ', 'Qisha polos seperti anak-anaknya. ', 'Qisha suka mewarnai. ', 'Terima', true, '2026-05-23 03:33:31.076'::timestamptz, '2026-05-23 03:33:31.076'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('06b34aa9-5582-4a0a-a9f9-660794e7835f'::uuid, 'f8897b60-2693-4ac9-9b34-b4ac998c754b'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Anak ke-2 dari 2 bersaudara. Rumah di jalan Kemang juga. ', 'Calistung sudah bisa, ngaji bisa Iqro. Toilet training sudah lulus.', 'Mendukung semua kegiatan sekolah.', 'Energik di rumah, tapi kalau di luar pemalu kecuali kalau sudah kenal lama. Kalau diminta tampil mau, tapi pelu waktu, harus nyaman dulu.', 'Tidak ada alergi.  Mohon bisa dioptimalkan agar ananda bisa berani tampil di depan umum. ', 'Terima', true, '2026-05-23 03:39:58.149'::timestamptz, '2026-05-23 03:39:58.149'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('a7bc139f-d80c-4963-9972-cd034111612a'::uuid, '7879613e-2201-468a-a9be-a34dc63f091d'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Arifah Hilyati, S.S, M.Pd', 'Gwenof sudah mandiri. Mandi sendiri, pakai bju sendiri. Toilet tranining bisa cebo sendiri. ', 'Gwenof bisa mengeja. Bisa menulis huruf, angka. Menghitung sudah sampai puluhan.', 'Bapak dan ibu intense  berkomunikasi. Gwenof siap jadi kakak. Adiknya iseng.', 'Di sekolah menutup diri. Membutuhkan waktu lama untuk bisa bersosialisasi dengan teman- temannya.', 'Left-handed. Menulis, makan left-handed. Tidak ada hambatan belajar. ', 'Terima', true, '2026-05-23 03:43:35.519'::timestamptz, '2026-05-23 03:43:35.519'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('aabc8db4-57b6-42dc-949c-7667fcdbafff'::uuid, '8e0b8107-8701-45b5-a036-82070b5bb129'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Anak ke-2 dari 2 bersaudara.Rumah di Gg. Bungur. anaknya seneng surat-surat pendek. November baru 7 tahun. Kakaknya di SD Erifhat kelas 2 SD.', 'Calistung sudah lancar, tapi tulisannya kurang bagus, n dan m, d dan p kadang suka terbalik. Gajinya di pesantren dekat rumah, jadi gajinya juga sudah belajar.', 'selalu mengusahakan untuk bisa hadir, karena ayah kerja di perhotelan, dan ibu kerja senin sampai Sabtu.', 'gampang terdistrak kalau ada temen. Kalau sedang makan, sering lari-larian juga sehingga waktu habis belum selesai makannya. Kalau di rumah manja, kalau di sekolah lebih dewasa. Mau belajar kalau disuruh.', 'Ibu Bapaknya kerja, sehingga anak sama nenek.', 'Terima', true, '2026-05-23 03:49:18.594'::timestamptz, '2026-05-23 03:49:18.594'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('4e2960fc-7b1c-4674-a633-04b83b57e70d'::uuid, '285edaa0-1de1-4c04-9bfb-f3ddf6e2c07d'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Anak kedua dari 2 bersaudara. Rumah di Bedahan.', 'Toilet training sudah mandiri, dan pernah ngompol di TK 2 kali, kalau tidur masih suka ngompol.  Calistung lancar. senang membaca. ', 'Ortu support setiap kegiatan di sekolah walaupun ayah dan ibunya kerja.', 'Anaknya mandiri, cepat menangkap pelajaran, dan suka mencari tahu. Berani tampil dan say hello ke orang-orang. Tapi juga cengeng, dan takut dengan ancaman temannya.', 'Di kelasnya yang sekarang di TK, ananda hanya sendirian, karena di kelas hanya 3 orang perempuannya, sementara yang 2 anak bersahabat. 2 anak itu namanya Adiba sama Azura dan juga daftar di Al Fakhir. Pesan ortu jangan dibuat 1 kelas dengan 2 anak tersebut.', 'Terima', true, '2026-05-23 04:02:02.743'::timestamptz, '2026-05-23 04:02:02.743'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('5e976754-7d66-4639-ad99-7f754956c289'::uuid, 'e8e49df6-a94a-4007-b5a3-34db18d1ef46'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Anak pertama dari 3 bersaudara. Sejauh ini tidak ada masalah di sekolah. Sudah belajar dasar-dasar berbahasa Inggris. ', 'Sudah mengenal huruf, tapi kalau ada kata ng, ny, itu agak sulit. Toilet training sudah lulus, paling saat BAB butuh dicek lagi. Mengaji masih Iqro.', 'Ortu support terhadap kegiatan sekolah. Ibunya di rumah, hanya ayah yang bekerja. ', 'Awalnya pemalu, setelah kenal anaknya rame, ceria, ramah. Anaknya cuek kalau ada yang jahil di sekolah. Sering ikut lomba menari. Masih sulit mengendalikan emosi karena jarak usia sama adik hanya 1 tahun.', 'Tidak ada alergi. ', 'Terima', true, '2026-05-23 04:19:58.658'::timestamptz, '2026-05-23 04:19:58.658'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('f7ae364f-c9a5-466b-8e74-7a7bb67fa4a0'::uuid, '3dccf4ae-d338-4071-8fa5-bdefd141fd43'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Anggraini, A.Md', 'Shahnaz sangat mandiri. Makan, minum, mandi, cebok sendiri. ', 'Sudah bisa membaca, menulis. Sudah bisa membaca Iqro'' 2. ', 'Komunikasi dengan orang tua sangat intense.  ', 'Ghaisanni sangat berempati, bisa membaca situasi.', 'Ananda suka make- up. Hari Kartini bisa make up sendiri.', 'Terima', true, '2026-05-23 04:21:16.526'::timestamptz, '2026-05-23 04:21:16.526'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('9c5cfe01-b7af-4732-81d3-bc940bdf5b27'::uuid, 'fedd1469-38fa-403d-b2d3-e8692290855e'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'tidak ada yang kurang semua bisa mengikuti dan siap dengan ', 'tidak ada kendala, anaknya mau sosialisai pingin ikut dan 5 besar, dan rajin ngaji, MTK dan bahasa inggris bagus nilainya, dan terakhir pringkat 2 di sekolah', 'tidak ada masalah dan ikut dengan peraturan ', 'sikapnya dewasa, dan sensitif suka ngambek dan  harus pelan dalm memberikan perintah,  subuh dan dan dhuha sudah terbiasa', 'menjadi lebih baik dan islamnya lebih baik lagi, ', 'Terima', true, '2026-06-12 01:25:36.373'::timestamptz, '2026-06-12 01:25:36.373'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('918f9e1c-2c13-4763-ac09-e27027b3cc21'::uuid, '807dece2-6518-401f-9da1-96f3e66ce768'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'sudah punya hafalan di juz 30 tapi belum selesai', 'untuk pelajaranya lancar dan nilainya tertinggi MTK, dan bahasa inggris, bahasa sunda', 'tidak ada masalah, untuk biasa tidak ada msalah dan sudah ok, ', 'anaknya tipe yang cerita sama orang tua, dan sudah mulai sadar untuk ibdanhnya', 'harapanya bisa menjawab, pelajaran arahan untuk agamanya dan akhlaqnya lebih baik', 'Terima', true, '2026-06-12 01:50:11.239'::timestamptz, '2026-06-12 01:50:11.239'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('df2828e6-6fdf-4429-aa98-c524f397a05f'::uuid, '963405b0-dc99-41ce-a1bc-604e59ec6c05'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Arifah Hilyati, S.S, M.Pd', 'Orang tua Fatah adalah guru Bahasa Jepang di SMA HelloMotion dan dosen di Universitas Sahid. Tinggal di Pasir putih. Ananda sudah sangat mandiri termasuk toliet training.', 'Fatah sudah bisa membaca tapi belum lancar.', 'Ananda sangat didukung oleh keluarga untuk belajar di Al Fakhir.', 'Fatah anak yang memiliki keingintahuan yang besar dan bernalar kristis. Dia akan paham jika diberitahu alasannya secara detail', 'Orang tua kooperatif dengan sekolah.', 'Terima', true, '2026-06-12 03:27:30.988'::timestamptz, '2026-06-12 03:27:30.988'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('2ff55f31-5f9c-4833-a1fa-af4457a7dba0'::uuid, 'a6cab318-d55f-4249-98fb-660b1aeb8b44'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'secara umum perkembangan ananda baik tidak ada hambatan', 'kesiapan belajara ananda sudah sesuai tahapannya', 'semoga semakin disiplin dan bisa terarah lagi, dan bisa lebih mandiri dan bertanggung jawab.', 'karakter ananda tidak ada masalah , hanya saja terkadang overthinking.', '-', 'Terima', true, '2026-06-23 01:38:19.999'::timestamptz, '2026-06-23 01:38:19.999'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('40141101-bd53-4668-867d-c4cfa593ca57'::uuid, 'ea70ad95-9f4a-4879-ae8f-cbdd5692a09d'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'secara umum ananda tidak ada kendala dalam perkembangan', 'ananda siap dan perkembangannya sesuai dengan tahapan usianya hanya saja tertinggal sedikit.', 'orangtua menyerahkan sepenuhnya pendidikan ke sekolah dan siap bekerja sama dengan pihak sekolah.', 'pendiam, percaya diri kurang ketika dengan guru atau orang lebih dewasa', 'mohon bantuan dibidang akakdemik karena SD nya sekolah karakter.', 'Terima', true, '2026-06-23 06:59:53.984'::timestamptz, '2026-06-23 06:59:53.984'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('849e99f4-63ab-49da-aef9-79c88898a080'::uuid, '1a58f6fc-7243-4b36-b974-8ae21d9c9a7e'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'sduah punya 3 juz ', 'alhamdulilah bisa mengikuti', 'mengikuti sejauh angka yang sudah tidak ada masalah', 'pendiam ketika di senggol gak terima dalam segi apapun, sudah terbiasa untuk melakukan ibadah', 'menemukan yang menjadi kebiasan di mana dan bisa lebih aktif', 'Terima', true, '2026-06-24 01:39:12.556'::timestamptz, '2026-06-24 01:39:12.556'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('23fb9f94-426f-4b03-a51d-f03fd74885a5'::uuid, 'fdda75ee-edf2-4bdd-8208-d2db3e36f842'::uuid, 'smpialfakhir@gmail.com', 'Mrs. Arifah Hilyati, S.S, M.Pd', 'anak pertama dari dua bersaudara', 'jasmin terbiasa interakasi bahasa inggris sehari hari dengan ayah dan bunda ada ketertarikan terhadap budaya jepang mulai dari ketertarikan menulis huruf jepang dan berbahasa jepang. jasmin minat dalam hal menggambar', 'ayah dan bunda ikut terlibat dalam hubungan kaka adik. ayah dan bunda juga mengsuport ketertarikan jasmin dalam beberapa hal. jasmin juga sudah terbisa di latih kemandiran hanya perlu di dukung lebih sering lagi.', 'jasmine adalah anak yang ramah. jika di hadapkan dengan kondisi sulit atau hal yg tidak iya suka jasmin akan lebih memilih menjauhkan diri dari kondisi tersebut. jasmin merupakan tipe anak yg lebih sering memperhatikan keadaan sekitar terlebih dahulu baru bisa bersosialisasi.', 'perlu di dukung dalm menumbuhakan percaya diri dan ke fokusan', 'Terima', true, '2026-06-30 02:44:34.399'::timestamptz, '2026-06-30 02:44:34.399'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('73fa039f-86c2-48e7-a69e-47fbbd678ea4'::uuid, '39932b15-b367-4f6e-a0f4-5ae06cf0a646'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', '3 juz, mengikuti', 'pindah karena biasa dekat dengan orang bahkan nilainya baik, tidak mengikutui', 'siap tidak masalah untuk biaya', 'tidak ada masalah, untuk sholat', NULL, 'Terima', true, '2026-07-14 01:59:07.539'::timestamptz, '2026-07-14 01:59:07.539'::timestamptz);
INSERT INTO catatan_pewawancara (id, kandidat_id, pewawancara_email, pewawancara_nama, observasi, penilaian_akademik, dukungan_keluarga, catatan_karakter, catatan_lain, rekomendasi, is_locked, created_at, updated_at) VALUES ('0ba065b7-6ffc-4c7f-9872-904090a9bc74'::uuid, '8ab3c1b5-f51f-49ca-8a42-dc7276c8d657'::uuid, 'smpialfakhir@gmail.com', 'Ustadz Deny Rahmat, S.Sos.I', 'hafaln 30,29, 28 dan 27 sedang berjalan', 'keunggulan mapel agama, akademik rendah itu di MTK. bahasa arabnya tinggi nilainya', 'sekolah yang di utamakan, dan tidak ada masalah ', 'dirumah banyak mengalah, dan ketika butuh sesuatu mengutarakan, lebih butuh pertimbangan, sudah terbiasa', NULL, 'Terima', true, '2026-07-14 02:14:38.449'::timestamptz, '2026-07-14 02:14:38.449'::timestamptz);
