INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('a9861534-75a6-40b6-a4b5-983b5eb768d9'::uuid, '7879613e-2201-468a-a9be-a34dc63f091d'::uuid, '**RINGKASAN INTI**: Gwennov menunjukkan kemandirian dasar, disiplin terukur (gadget, tidur, sholat), minat belajar (seni, hitung, cerita), serta adaptasi sosial yang baik dan konsentrasi efektif. Keluarga sangat suportif, berkomitmen pada pendidikan agama, dan proaktif mengidentifikasi membaca sebagai area stimulasi.\n\n**KESELARASAN**: 90%\n**POIN UTAMA**: Kemandirian tinggi, Disiplin rutin, Minat belajar, Keluarga suportif\n**RED FLAGS**: Nihil\n**REKOMENDASI SKOR**: 9/10', '2026-05-23 01:09:55.936'::timestamptz, '2026-05-23 01:09:55.936'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('7fd7847e-7882-490e-a5a8-5fbc9b99bc0d'::uuid, 'd338abc5-cdca-4c3c-809e-246b51437c12'::uuid, '**RINGKASAN INTI**: Muhaira Nalahudin menunjukkan kemandirian dasar yang baik, rutinitas teratur, serta minat kuat pada visual dan potensi seni (puisi). Ia proaktif bertanya dan mampu mengikuti instruksi.\n**KESELARASAN**: 90%\n**POIN UTAMA**: Mandiri, Rutin Teratur, Visual Aktif, Potensi Seni\n**RED FLAGS**: Mudah terdistraksi\n**REKOMENDASI SKOR**: 8.5/10', '2026-05-23 01:12:38.955'::timestamptz, '2026-05-23 01:12:38.955'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('3e64c637-cfc9-46c0-b2b6-5184e67882a3'::uuid, '0b1ad581-4655-416e-80db-7a8b5bee0e37'::uuid, '**RINGKASAN INTI**: Zeeryu menunjukkan kemandirian tinggi, fondasi agama kuat, serta minat belajar visual pada seni dan bahasa asing. Keluarga sangat suportif, proaktif, dan selaras dengan nilai pendidikan serta program sekolah.\n**KESELARASAN**: 95%\n**POIN UTAMA**:\n1.  Kemandirian & Disiplin\n2.  Minat Bahasa & Visual\n3.  Dasar Islam Kuat\n4.  Dukungan Keluarga Aktif\n**RED FLAGS**: Kidal (menulis), membutuhkan stimulasi percaya diri.\n**REKOMENDASI SKOR**: 9/10', '2026-05-23 01:12:50.747'::timestamptz, '2026-05-23 01:12:50.747'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('048a3786-a816-4450-bec2-e81bb2178f1d'::uuid, '10cb2948-f458-4201-a335-22a6a7b052f2'::uuid, '**RINGKASAN INTI**: Calon siswa menunjukkan kemandirian tinggi, fondasi akademik dan agama baik, serta bakat seni menonjol. Area pengembangan utama adalah regulasi emosi dan ketahanan saat menghadapi kesulitan belajar.\n**KESELARASAN**: 95%\n**POIN UTAMA**:\n*   Mandiri & Saleh\n*   Bakat Seni Menonjol\n*   Konsentrasi Baik\n*   Dukungan Ortu Kuat\n**RED FLAGS**:\n*   Regulasi Emosi Marah (membutuhkan ruang pribadi sebelum dialog)\n*   Cenderung berhenti saat kesulitan belajar\n**REKOMENDASI SKOR**: 9/10', '2026-05-23 01:14:46.017'::timestamptz, '2026-05-23 01:14:46.017'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('951c68cc-03cc-4e93-b79c-d6c4176ea079'::uuid, '43f0bed0-6a5c-4bc2-9485-3c3315ce89d1'::uuid, '**RINGKASAN INTI**: Nadiara menunjukkan kemandirian, kesiapan belajar, dan minat kuat pada Al-Qur''an serta kisah Nabi, didukung bakat pildacil. Keluarga berkomitmen tinggi pada pendidikan Islam holistik, selaras penuh dengan visi sekolah dan kesediaan kerjasama.\n**KESELARASAN**: 95%\n**POIN UTAMA**: Kemandirian Kuat, Minat Qur''ani, Bakat Pildacil, Komitmen Keluarga\n**RED FLAGS**: Nihil\n**REKOMENDASI SKOR**: 9.5/10', '2026-05-23 01:07:53.264'::timestamptz, '2026-05-23 01:07:53.264'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('ea574779-8b81-459d-b118-03bb01b391ec'::uuid, 'f5cf3f10-0359-45bf-bd3c-38693b4cc08a'::uuid, '**RINGKASAN INTI**: Keenan menunjukkan kemandirian dasar, fondasi agama kuat (Iqro 2, hafalan surat, sholat), serta potensi hafalan Al-Qur''an dan seni/olahraga. Ia adaptif dan didukung orang tua yang sangat terlibat, meskipun memiliki diagnosa autisme ringan yang mempengaruhi konsentrasi dan regulasi emosi.\n**KESELARASAN**: 95%\n**POIN UTAMA**:\n*   Kemandirian & Fondasi Islami\n*   Potensi Hafalan & Seni\n*   Autisme Ringan\n*   Dukungan Ortu Aktif\n**RED FLAGS**: Autisme ringan; Konsentrasi fluktuatif; Regulasi emosi (ngambek/diam).\n**REKOMENDASI SKOR**: 8.5/10', '2026-05-23 01:19:35.467'::timestamptz, '2026-05-23 01:19:35.467'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('cdbfb86a-4d61-4c95-8080-80d6a655ed3d'::uuid, 'd558d345-77fd-41ad-9216-d15aed2564a0'::uuid, '**RINGKASAN INTI**: Orang tua menunjukkan komitmen kuat terhadap pendidikan Zaidaan dan siap berkolaborasi; Zaidaan memiliki potensi akademik baik namun memerlukan stimulasi kemandirian dan pengelolaan emosi.\n**KESELARASAN**: 95%\n**POIN UTAMA**: Komitmen Ortu Tinggi, Potensi Berhitung, Tantrum, Kemandirian Dasar.\n**RED FLAGS**: Tantrum (kesulitan belajar/beda pendapat), Kemandirian dasar (makan/toilet) belum.\n**REKOMENDASI SKOR**: 7.5/10', '2026-05-23 01:19:50.589'::timestamptz, '2026-05-23 01:19:50.589'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('270aa24f-b2b0-468a-a7a1-5aaa08c8e196'::uuid, '8e0b8107-8701-45b5-a036-82070b5bb129'::uuid, '**RINGKASAN INTI**: Syafira menunjukkan kemandirian pribadi, minat seni/agama, serta dasar ibadah yang baik, namun memerlukan stimulasi intensif untuk meningkatkan fokus dan konsistensi belajar. Keluarga sangat mendukung pengembangan agama dan akademik, menyadari tantangan anak dan siap bekerja sama meskipun dengan keterbatasan kehadiran fisik.\n\n**KESELARASAN**: 90%\n**POIN UTAMA**: Kemandirian, Gaya Belajar Kinestetik, Perlu Stimulasi Fokus, Dukungan Keluarga\n**RED FLAGS**: Kurang fokus, kebiasaan belajar perlu pengingat, keterbatasan kehadiran orang tua di acara sekolah.\n**REKOMENDASI SKOR**: 8/10', '2026-05-23 01:22:17.639'::timestamptz, '2026-05-23 01:22:17.639'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('385127fc-ab31-4d27-9377-db17dbe905f5'::uuid, '807dece2-6518-401f-9da1-96f3e66ce768'::uuid, '**RINGKASAN INTI**: Bima menunjukkan kemandirian dasar dan nilai PAI kuat, namun motivasi bersekolah utamanya berasal dari orang tua. Potensi adaptasi sosial dan proaktivitas dalam mengatasi tantangan perlu pendampingan lebih lanjut, diiringi pengembangan kefasihan membaca Al-Qur''an.\n**KESELARASAN**: Data jawaban orang tua tidak tersedia untuk perbandingan.\n**POIN UTAMA**: Kemandirian, PAI Kuat, Motivasi Eksternal, Adaptasi Terbatas.\n**RED FLAGS**: Motivasi Eksternal, Adaptasi Sosial, Sikap Pasif (Guru), Kefasihan Al-Qur''an.\n**REKOMENDASI SKOR**: 7/10', '2026-06-12 01:49:17.58'::timestamptz, '2026-06-12 01:49:17.58'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('a3c35e2b-442d-4588-9dfd-209388d0a179'::uuid, '652e2fba-0160-4627-9dce-74e7474989cb'::uuid, '**RINGKASAN INTI**: Nasheeta memiliki fondasi spiritual dan minat kuat pada bahasa, didukung komitmen keluarga. Ia memerlukan stimulasi kemandirian, adaptasi sosial, kepercayaan diri, dan peningkatan penguasaan Matematika.\n\n**KESELARASAN**: 85%. Terdapat keselarasan tinggi pada data spiritual, rutinitas, dan tantangan adaptasi. Perbedaan nuansa pada detail keakraban keluarga, kemandirian (optimisme siswa), dan komitmen kehadiran orang tua. Terdapat inkonsistensi signifikan pada identifikasi mata pelajaran favorit antara siswa dan orang tua, meskipun ada kesamaan minat pada Bahasa.\n\n**POIN UTAMA**: Spiritual, Minat Bahasa, Adaptasi & Kepercayaan diri, Kendala Matematika.\n\n**RED FLAGS**: Inkonsistensi Mapel Favorit, Waktu layar (gadget) 3-4 jam/hari, Sikap pasif dalam resolusi konflik, Kebutuhan stimulasi kepercayaan diri.\n\n**REKOMENDASI SKOR**: 7.5/10', '2026-07-14 01:35:55.748'::timestamptz, '2026-07-14 01:35:55.748'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('e021c483-4f59-4348-b0e4-aa65397baeaf'::uuid, '8ab3c1b5-f51f-49ca-8a42-dc7276c8d657'::uuid, '**RINGKASAN INTI**: Nada adalah calon siswa berprestasi tinggi di bidang akademik dan keagamaan (tahfiz), menunjukkan kemandirian baik serta dukungan keluarga. Namun, terdapat indikasi kebutuhan pendampingan adaptasi awal lingkungan baru dan penyesuaian gaya belajar spesifik.\n\n**KESELARASAN**: 80% (Data mayoritas selaras, namun terdapat perbedaan nuansa pada adaptasi sosial, hobi, dan konsistensi ibadah sunnah).\n\n**POIN UTAMA**: Prestasi Cemerlang, Religius (Tahfiz), Mandiri, Gaya Belajar Spesifik.\n\n**RED FLAGS**: Adaptasi Awal Lingkungan (menurut ortu), Sensitif saat ditegur/Percaya Diri Rendah (menurut ortu), Ketergantungan Latihan Soal untuk Pemahaman (menurut siswa).\n\n**REKOMENDASI SKOR**: 8.8/10', '2026-07-14 01:41:17.713'::timestamptz, '2026-07-14 01:41:17.713'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('1c428625-11bc-474f-9ad0-465d75d31701'::uuid, '80fca573-b109-4a19-9047-f863617d23d5'::uuid, '**Analisis Utama**: Kanaya adalah calon siswa ekstrovert dengan kemandirian sosial yang baik dan dukungan orang tua yang kuat, namun memiliki profil emosional sensitif yang memerlukan pendekatan persuasif (tidak bisa dikerasin).\n\n**Persentase Keselarasan**: 90% (Data menunjukkan sinkronisasi tinggi antara perilaku anak di rumah dengan persepsi orang tua, namun terdapat ambiguitas pada prestasi MIPA vs kendala Matematika).\n\n**Kekuatan**:\n*   **Karakter & Sosial**: Ekstrovert, mudah beradaptasi, sopan, dan memiliki tanggung jawab rumah tangga yang baik (mandiri).\n*   **Akademik & Minat**: Minat sangat kuat pada literasi agama (Bahasa Arab, Fiqih, SKI) dan aktif dalam kegiatan non-akademik (seni/organisasi).\n*   **Dukungan Wali**: Orang tua kooperatif, siap terlibat dalam program sekolah, dan menghargai pilihan anak.\n\n**Red Flags/Perhatian**:\n*   **Regulasi Emosi**: Suara meninggi saat marah dan cenderung memendam masalah (diam) lalu hanya bercerita pada Ibu, bukan menyelesaikan langsung.\n*   **Respon Terhadap Otoritas**: Orang tua menyebut anak "tidak bisa dikerasin," yang perlu diantisipasi dalam pemberian disiplin/konsekuensi di sekolah.\n*   **Hafalan Al-Qur''an**: Belum memiliki hafalan, memerlukan matrikulasi intensif untuk mengejar standar SMP Al Fakhir.\n\n**Tanya Saat Wawancara**:\n1. "Ananda pernah juara MIPA, namun merasa Matematika adalah kendala; bagian mana dari Matematika yang dirasa paling sulit?"\n2. "Bagaimana respon Ananda jika berada dalam situasi konflik kelompok di mana Ibu tidak ada di tempat untuk mendengarkan cerita Ananda?"\n\n**Skor Kesesuaian**: 8.5/10 (Sangat sesuai dengan lingkungan Al Fakhir, dengan catatan pendampingan pada penguatan hafalan Al-Qur''an dan manajemen emosi).', '2026-05-09 00:57:02.211'::timestamptz, '2026-05-09 00:57:02.211'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('332dd394-0b71-4f22-9d51-10a0252c282b'::uuid, '5c9ace2c-6b2f-45f7-8cc0-36bb789d293d'::uuid, '**Analisis Utama**: Irsyad adalah calon siswa dengan kepribadian santun namun memiliki tantangan besar dalam hal kemandirian, tanggung jawab, dan kepercayaan diri. Orang tua sangat transparan mengenai sifat anak yang "cuek" dan membutuhkan pengawasan ketat.\n\n**Persentase Keselarasan**: 95% (Data sangat konsisten; orang tua secara jujur mengakui kelemahan anak di berbagai poin pertanyaan, menunjukkan reliabilitas informasi yang tinggi).\n\n**Kekuatan**:\n*   Memiliki adab yang baik (sopan kepada guru, orang dewasa, dan teman).\n*   Menyukai mata pelajaran Akidah Akhlak (potensi pembentukan karakter).\n*   Sudah memiliki dasar bacaan Al-Qur''an (Tilawati) dan hafalan dasar.\n*   Dukungan penuh dari orang tua terhadap program sekolah.\n\n**Red Flags/Perhatian**:\n*   Kemandirian rendah: Harus selalu diingatkan untuk ibadah, tugas, dan aturan.\n*   Rasa tanggung jawab kurang: Cenderung santai/cuek meskipun tugas menumpuk atau melakukan kesalahan.\n*   Adaptasi lambat: Membutuhkan waktu lama di lingkungan baru dan cenderung menarik diri (diam/menyendiri) saat ada masalah.\n*   Kepercayaan diri rendah (sering merasa malu/takut).\n\n**Tanya Saat Wawancara**:\n1.  Untuk Irsyad: "Apa yang biasanya membuatmu merasa malas atau enggan memulai tugas jika tidak ditegur oleh Bunda?"\n2.  Untuk Orang Tua: "Sejauh mana batas toleransi orang tua terhadap sifat ''cuek'' anak sebelum memberikan konsekuensi tegas?"\n\n**Skor Kesesuaian**: 7/10 (Sangat membutuhkan lingkungan Al Fakhir untuk stimulasi karakter, namun sekolah harus siap dengan pendampingan ekstra di bidang akademik dan kedisiplinan).', '2026-05-09 00:45:51.261'::timestamptz, '2026-05-09 00:45:51.261'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('108304d1-e1cc-48cc-abac-7bdb2f9e519b'::uuid, '9226a3db-81a9-4a25-857f-0a634ad03d34'::uuid, '**Analisis Utama**: Danendra memiliki potensi akademik (Matematika) dan non-akademik (olahraga) yang baik, namun menunjukkan tantangan signifikan pada aspek kemandirian, regulasi emosi, dan kedisiplinan.\n\n**Persentase Keselarasan**: 65% (Terdapat kontradiksi serius pada komitmen orang tua serta indikasi rendahnya ketahanan mental anak dalam menghadapi tekanan akademik).\n\n**Kekuatan**:\n*   **Akademik & Minat**: Menyukai Matematika dan aktif dalam olahraga (Futsal & Badminton).\n*   **Religiusitas Dasar**: Sudah lancar membaca Al-Qur''an dan mulai menjalankan puasa sunnah.\n*   **Sosial**: Memiliki sikap sopan kepada orang dewasa, mampu beradaptasi, dan berani berargumentasi saat berbeda pendapat.\n\n**Red Flags/Perhatian**:\n*   **Kontradiksi Komitmen**: Orang tua menyatakan **"Tidak"** bersedia bekerja sama dengan sekolah terkait perkembangan anak, padahal di sisi lain bersedia hadir dalam acara sekolah.\n*   **Kemandirian Rendah**: Masih perlu diingatkan untuk sholat, tanggung jawab terhadap tugas masih kurang, dan sering mengeluh jika menghadapi kesulitan.\n*   **Regulasi Emosi**: Ekspresi marah/kecewa masih kekanak-kanakan (menangis/ngambek) dan kurang tangguh (fragile) saat menghadapi beban tugas.\n\n**Tanya Saat Wawancara**:\n1.  **Klarifikasi Komitmen**: Mengapa orang tua menyatakan tidak bersedia bekerja sama dengan sekolah terkait perkembangan anak?\n2.  **Daya Juang (Grit)**: Bagaimana langkah konkret orang tua dalam melatih kemandirian anak agar tidak mudah mengeluh dan menyerah saat menghadapi kesulitan belajar di tingkat SMP?\n\n**Skor Kesesuaian**: 6.5/10\n*(Skor ini mempertimbangkan potensi anak yang bagus, namun terhambat oleh sikap mental "mengeluh" dan inkonsistensi jawaban orang tua terkait kemitraan dengan sekolah).*', '2026-05-09 00:50:36.48'::timestamptz, '2026-05-09 00:50:36.48'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('df849cc2-7bff-4155-a2b7-4bf81b4f2fa8'::uuid, 'ded7f787-2d41-433a-a127-a5d8a2224340'::uuid, '- **Analisis Utama**: Ghendis adalah calon siswa yang kooperatif dan adaptif dengan dukungan penuh dari orang tua yang proaktif dalam pendampingan belajar serta pembentukan karakter disiplin.\n- **Persentase Keselarasan**: 90% (Data sangat selaras terkait pola komunikasi, hobi, dan karakter; terdapat sedikit inkonsistensi pada detail capaian hafalan dan indikasi typo pada jam bangun tidur).\n- **Kekuatan**:\n    - Orang tua sangat suportif dan siap memfasilitasi kebutuhan akademik (kursus/bimbel).\n    - Memiliki dasar tahfidz dan bakat seni (menari).\n    - Kecerdasan emosional dalam berinteraksi sosial (mudah beradaptasi dan menghargai perbedaan pendapat).\n- **Red Flags/Perhatian**:\n    - Kemandirian belajar masih rendah (sangat bergantung pada solusi/instruksi orang tua saat menghadapi kendala).\n    - Motivasi memilih sekolah hanya didasari faktor jarak ("Terdekat"), bukan visi/program sekolah.\n    - Tertulis jam bangun tidur pukul 16.00 (kemungkinan besar *typo* dari 04.00 atau 06.00, namun perlu dipastikan).\n- **Tanya Saat Wawancara**:\n    1. Konfirmasi ulang rutinitas harian, khususnya jam bangun tidur dan kemandirian sholat Subuh.\n    2. Klarifikasi progres hafalan: Apakah sudah tuntas Juz 30 dan sedang di Juz 29, atau hanya salah satu?\n- **Skor Kesesuaian**: 8/10', '2026-05-09 01:02:25.906'::timestamptz, '2026-05-09 01:02:25.906'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('8bdb0acb-8bf7-4d1e-86d9-56f8e89dd826'::uuid, 'ac374288-1322-4e08-8e85-58c47891fbbe'::uuid, '- **Analisis Utama**: Calon siswa memiliki kemandirian domestik yang baik dan prestasi non-akademik (Karate), namun memerlukan pengawasan pada disiplin waktu dan pendampingan khusus terkait riwayat ADHD.\n- **Persentase Keselarasan**: 95% (Data menunjukkan kejujuran orang tua dalam mengungkap riwayat medis dan kelemahan siswa, selaras dengan observasi karakter yang masih perlu distimulasi).\n- **Kekuatan**:\n    - Prestasi non-akademik (Juara Karate).\n    - Adaptasi sosial tinggi dan memiliki adab yang baik (sopan kepada guru/orang tua).\n    - Mandiri dalam tugas rumah tangga (memasak nasi, merapikan tempat tidur).\n    - Memiliki minat spesifik yang kuat (Bahasa Inggris dan Catur).\n- **Red Flags/Perhatian**:\n    - Riwayat ADHD: Membutuhkan informasi lebih lanjut mengenai fokus dan manajemen kelas.\n    - Regulasi Emosi: Masih menangis saat marah/kecewa (perlu penguatan mental).\n    - Pola Tidur: Jam tidur pukul 22.30 terlalu larut untuk usia sekolah, berisiko pada konsentrasi pagi hari.\n    - Ibadah & Belajar: Masih bersifat pasif (perlu diingatkan).\n- **Tanya Saat Wawancara**: \n    1. Bagaimana bentuk perilaku ADHD yang masih sering muncul saat ini dan bagaimana cara guru di sekolah sebelumnya menangani hal tersebut?\n    2. Apa kendala utama yang menyebabkan ananda tidur larut malam dan bagaimana dampaknya terhadap kesiapan bangun pagi?\n- **Skor Kesesuaian**: 8/10 (Sangat potensial untuk dibentuk, asalkan sekolah siap dengan dukungan inklusi/pendampingan ADHD).', '2026-05-09 01:11:26.385'::timestamptz, '2026-05-09 01:11:26.385'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('5e2d190a-215b-4123-95a3-065ab6112665'::uuid, '3ae035bb-c1ae-4334-9677-00f9a8f06145'::uuid, '**Analisis Utama**: Chaidar adalah calon siswa yang mandiri dan berprestasi secara akademik (Top 5), namun memiliki tantangan signifikan pada aspek konsentrasi (fokus) dan regulasi emosi saat menghadapi tekanan tugas.\n\n**Persentase Keselarasan**: 95% (Data menunjukkan konsistensi tinggi antara profil anak yang aktif/tidak bisa diam dengan kendala fokus dan respons emosional yang dilaporkan orang tua).\n\n**Kekuatan**:\n*   **Akademik & Religius**: Konsisten masuk peringkat 5 besar, memiliki hafalan Juz 30, dan menyukai mata pelajaran Qurdis.\n*   **Kemandirian**: Terbiasa mandiri di rumah karena kedua orang tua bekerja dan memiliki kemampuan adaptasi lingkungan yang baik.\n*   **Kedisiplinan**: Jadwal tidur dan bangun (04.00) sangat teratur; memiliki figur otoritas yang dihormati (Ayah).\n\n**Red Flags/Perhatian**:\n*   **Fokus & Hiperaktivitas**: Orang tua berulang kali menekankan bahwa anak "tidak bisa diam" dan sulit fokus.\n*   **Regulasi Emosi**: Masih menunjukkan sikap "rewel" saat menghadapi tugas berat dan menangis jika kecewa (perlu pendampingan kematangan emosi SMP).\n*   **Ibadah**: Sholat lima waktu masih perlu diingatkan (belum menjadi kesadaran internal sepenuhnya).\n\n**Tanya Saat Wawancara**:\n1.  Untuk Anak: "Bagaimana cara kamu menenangkan diri atau menyelesaikan tugas jika merasa tugas tersebut sangat sulit dan menumpuk?"\n2.  Untuk Orang Tua: "Sejauh mana orang tua dapat mentoleransi dan mendukung program sekolah jika perilaku ''tidak bisa diam'' anak mengganggu efektivitas belajarnya di kelas?"\n\n**Skor Kesesuaian**: 8/10 (Sangat potensial secara akademik dan karakter dasar, namun memerlukan perhatian khusus pada pengembangan fokus dan manajemen stres).', '2026-05-09 01:18:47.798'::timestamptz, '2026-05-09 01:18:47.798'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('a5baed5a-6fa2-4259-97d1-5e8c07dc06b6'::uuid, '546d4f58-be7e-4f91-8c82-fe814b1522bb'::uuid, '**Analisis Utama**: Akbar adalah calon siswa yang memiliki potensi non-akademik kuat (atlet O2SN) dan karakter yang kooperatif serta mandiri dalam kebiasaan rumah, namun masih memerlukan penguatan motivasi internal untuk ibadah wajib.\n\n**Persentase Keselarasan**: 95% (Data menunjukkan sinkronisasi yang kuat antara ekspektasi orang tua dengan profil aktivitas harian siswa, khususnya pada hobi, prestasi, dan kebiasaan di rumah).\n\n**Kekuatan**:\n*   **Prestasi Non-Akademik**: Juara 2 O2SN Badminton; menunjukkan kedisiplinan dan jiwa kompetitif.\n*   **Kemandirian & Adabtasi**: Terbiasa dengan aturan rumah (beres-beres mandiri) dan mudah beradaptasi karena pengalaman mengikuti berbagai les (gitar, renang, badminton).\n*   **Karakter**: Sopan kepada orang tua/guru dan memiliki manajemen emosi yang tenang (diam saat ditegur/marah).\n*   **Akademik**: Memiliki minat pada Bahasa Inggris dan sudah menyelesaikan hafalan Juz 30.\n\n**Red Flags/Perhatian**:\n*   **Ibadah**: Masih perlu diingatkan untuk shalat 5 waktu (belum kesadaran mandiri).\n*   **Respon Konflik**: Kecenderungan "diam" saat marah atau beda pendapat perlu dipastikan apakah bentuk regulasi diri atau perilaku pasif-agresif/pendam masalah.\n*   **Catatan Bullying**: Terdapat perhatian khusus orang tua terkait "Bully Fisik", perlu dipastikan apakah Akbar adalah penyintas atau memiliki trauma tertentu.\n*   **Akademik**: Kendala pada Bahasa Sunda.\n\n**Tanya Saat Wawancara**:\n1.  "Bisa ceritakan lebih lanjut mengenai catatan ''bully fisik'' yang disebutkan orang tua? Bagaimana pengalaman Akbar terkait hal tersebut?"\n2.  "Saat Akbar merasa marah dan memilih diam, apa yang biasanya Akbar rasakan atau pikirkan saat itu?"\n\n**Skor Kesesuaian**: 8.5/10 (Sangat sesuai dengan visi Al Fakhir dalam pembentukan akhlak dan kelanjutan hafalan, dengan catatan pendampingan pada aspek kemandirian ibadah).', '2026-05-09 01:19:06.252'::timestamptz, '2026-05-09 01:19:06.252'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('ae7d63d9-1c81-4795-9d4f-646950c7689b'::uuid, '9c71f848-1bda-4b67-89a8-d624b9cb90a5'::uuid, '- **Analisis Utama**: Calon siswa menunjukkan kemandirian tinggi dalam ibadah dan akademik (Matematika), namun orang tua mengidentifikasi adanya kebutuhan mendalam pada penguatan etika dan pendewasaan diri.\n- **Persentase Keselarasan**: 90% (Data sangat selaras; profil anak yang mandiri dan berprestasi didukung penuh oleh komitmen orang tua terhadap nilai-nilai sekolah).\n- **Kekuatan**: Ibadah 5 waktu mandiri, lancar baca Al-Qur''an, memiliki prestasi (futsal & kaligrafi), dan memiliki sikap terbuka terhadap konsekuensi/teguruan.\n- **Red Flags/Perhatian**: Adanya catatan orang tua mengenai perlunya penguatan "Etika" dan "Pendewasaan diri," yang kontras dengan deskripsi anak yang disebut sudah "Sopan" dan "Humble."\n- **Tanya Saat Wawancara**: \n    1. "Dalam situasi seperti apa orang tua merasa etika Ananda masih perlu dikuatkan?"\n    2. "Bagaimana cara Ananda mengelola emosi selain menunjukkan wajah kesal saat terjadi perbedaan pendapat?"\n- **Skor Kesesuaian**: 9/10 (Sangat sesuai dengan profil sekolah Islam Modern Al Fakhir).', '2026-05-09 01:22:05.141'::timestamptz, '2026-05-09 01:22:05.141'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('c6c603d1-c8dc-43ad-95f4-c2e6edbca5d7'::uuid, 'b37a2a0b-5122-49b0-98d9-13b0b8ca2061'::uuid, '- **Analisis Utama**: Lintang adalah calon siswa dengan profil non-akademik yang kuat (Karate & Bahasa Inggris) dan kemampuan sosialisasi yang baik, namun masih memiliki ketergantungan tinggi pada pendampingan orang tua dalam hal kemandirian dan kedisiplinan ibadah.\n\n- **Persentase Keselarasan**: 95% (Jawaban orang tua sangat detail dan objektif dalam mengakui kekurangan anak, menunjukkan transparansi yang tinggi antara kondisi riil siswa dengan ekspektasi orang tua).\n\n- **Kekuatan**:\n    - Prestasi non-akademik nyata (Juara Karate kategori Kumite).\n    - Kecerdasan emosional baik (mampu mengungkapkan perasaan secara verbal dan berdiskusi).\n    - Kemampuan adaptasi sosial yang tinggi dan inklusif dalam berteman.\n    - Minat pada literasi bahasa (Lagu Inggris) dan IPAS.\n\n- **Red Flags/Perhatian**:\n    - **Kemandirian**: Masih perlu diingatkan untuk sholat, tugas, dan tanggung jawab dasar.\n    - **Regulasi Emosi**: Masih sering menangis saat menghadapi kekecewaan/marah (perlu transisi kedewasaan untuk usia SMP).\n    - **Akademik**: Kendala pada mata pelajaran Matematika yang akan semakin kompleks di jenjang SMP.\n\n- **Tanya Saat Wawancara**:\n    1. "Bagaimana rencana Lintang jika nanti di SMP tugas sekolah lebih banyak dan tidak selalu bisa didampingi Ibu?"\n    2. "Apa yang biasanya membuat Lintang merasa paling sulit untuk memulai sholat atau tugas tanpa diingatkan?"\n\n- **Skor Kesesuaian**: 8.5/10 (Sangat sesuai dengan visi sekolah yang islami dan modern; profil siswa yang aktif dan suportivitas orang tua yang tinggi menjadi modal besar perkembangan di Al Fakhir).', '2026-05-09 01:30:07.149'::timestamptz, '2026-05-09 01:30:07.149'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('159437ad-67ea-4a19-aae2-95fff09c7561'::uuid, '7e025f84-a676-4a98-bc66-4a9b496a756b'::uuid, '**Analisis Utama**: Sky Zumar adalah calon siswa yang sopan, disiplin dalam rutinitas fisik, namun memiliki tantangan besar dalam kepercayaan diri sosial dan kemandirian belajar. Terdapat sedikit ambivalensi antara minat pada Tahfidz dengan ketergantungan tinggi pada gadget (game).\n\n**Persentase Keselarasan**: 85% (Secara internal terdapat kontradiksi kecil antara klaim "patuh aturan rumah secara konsisten" dengan fakta "sholat masih perlu diingatkan").\n\n**Kekuatan**:\n*   **Kedisiplinan Waktu**: Memiliki pola tidur-bangun yang sangat teratur (jam 10 malam - jam 6 pagi).\n*   **Adab**: Memiliki sikap sopan terhadap guru, orang tua, dan menerima konsekuensi dengan diam/patuh.\n*   **Literasi Qur''an**: Sudah lancar membaca Al-Qur''an dan telah menyelesaikan Juz 30.\n\n**Red Flags/Perhatian**:\n*   **Gadget**: Durasi bermain game 2-4 jam/hari tergolong tinggi dan berisiko mengganggu fokus akademik.\n*   **Karakter Tertutup**: Sangat introvert, cenderung diam saat konflik/marah, dan lebih banyak mengalah (perlu stimulasi untuk kemampuan bicara/assertive).\n*   **Kemandirian Rendah**: Masih bergantung penuh pada bantuan orang tua saat menghadapi kesulitan tugas sekolah.\n\n**Tanya Saat Wawancara**:\n1.  "Bagaimana cara Ananda mengatur waktu antara hobi bermain game dengan target hafalan Al-Qur''an?"\n2.  "Jika ada teman yang mengambil barang milikmu tanpa izin, apakah kamu tetap akan diam/mengalah atau melaporkannya ke guru?"\n\n**Skor Kesesuaian**: 7.5/10 (Sangat cocok dengan label ''Modern-Digital'' Al Fakhir, namun butuh bimbingan intensif dari guru BK/Wali Kelas untuk menguatkan sisi ekspresif dan sosialnya).', '2026-05-09 01:30:44.713'::timestamptz, '2026-05-09 01:30:44.713'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('a2027e1d-18fb-477d-a7dc-568b7ab857ff'::uuid, '4fdc98d1-4eed-4576-ba9b-7a57044583c5'::uuid, '**Analisis Utama**:\nMuhammad Zenobi Arkanta menunjukkan tingkat keselarasan informasi yang rendah antara persepsi dirinya dan observasi orang tua, terutama terkait kemandirian, ibadah, dan prestasi. Meskipun memiliki potensi pada Bahasa Inggris dan dukungan orang tua yang kuat, ia perlu stimulasi signifikan dalam hal kesadaran diri, kemampuan ekspresi, dan motivasi intrinsik.\n\n**Persentase Keselarasan**: 35%\n\n**Kekuatan**:\n*   Minat pada Bahasa Inggris dan musik (sesuai dengan program sekolah "English day").\n*   Ada indikasi disiplin dalam rutinitas harian tertentu (tidur/bangun tepat waktu, shalat subuh tanpa diingatkan menurut orang tua).\n*   Kemampuan adaptasi yang baik terhadap lingkungan baru (meskipun diawali dengan rasa malu).\n*   Dukungan dan komitmen tinggi dari orang tua terhadap program dan kerja sama dengan sekolah.\n\n**Red Flags/Perhatian**:\n*   Tingkat kesadaran diri siswa yang sangat rendah (tidak tahu kelebihan/kekurangan, tidak ingat hafalan/prestasi).\n*   Banyak kontradiksi signifikan antara jawaban siswa dan orang tua (misalnya: jumlah saudara, akrab dengan keluarga, mandiri/disiplin, shalat tanpa diingatkan, hafalan, hingga prestasi).\n*   Kesulitan dalam mengekspresikan diri dan kecenderungan untuk diam atau menghindar saat menghadapi masalah/ketidaksepakatan.\n*   Minimnya motivasi intrinsik siswa dalam memilih sekolah (murni pilihan orang tua).\n*   Perilaku pemalu dan kurang fokus saat membaca soal panjang (cerita).\n*   Siswa menyatakan "tidak memiliki teman akrab", berbeda dengan orang tua yang menyebut "teman dekat".\n*   Riwayat penyakit sinus (alergi debu) yang memerlukan perhatian.\n\n**Tanya Saat Wawancara**:\n1.  Berapa sebenarnya jumlah saudara kandung Zenobi?\n2.  Bisa Zenobi ceritakan tentang Juara 3 Lomba Bahasa Inggris yang diraihnya dan mengapa tidak disebutkan sebelumnya?\n3.  Bagaimana rutinitas ibadah harian Zenobi, terutama shalat lima waktu dan mengaji di rumah?\n\n**Skor Kesesuaian**: 5/10', '2026-05-09 01:57:05.528'::timestamptz, '2026-05-09 01:57:05.528'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('b6f46cb8-7eca-4e8a-963d-c84c3cef9c36'::uuid, 'c11f634e-8a0a-4b05-b4cb-320e647ab90e'::uuid, '**RINGKASAN INTI**:\nMisha menunjukkan kemandirian dasar yang baik, fondasi agama yang kuat, dan kemampuan adaptasi sosial positif. Orang tua memiliki komitmen tinggi terhadap pendidikan Misha serta kesediaan bekerja sama, dengan fokus pada stimulasi kemampuan membaca/mengaji.\n\n**KESELARASAN**: 95%\n**POIN UTAMA**:\n*   Kemandirian Primer\n*   Fondasi Islami Kuat\n*   Adaptasi Sosial Baik\n*   Komitmen Ortu Tinggi\n**RED FLAGS**: Nihil\n**REKOMENDASI SKOR**: 9/10', '2026-05-23 01:26:17.53'::timestamptz, '2026-05-23 01:26:17.53'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('c2c2b1b9-b583-43cd-b1f3-f04c32fc07e7'::uuid, 'a9939d1a-ea4f-4652-9ac9-d3cfa5dae379'::uuid, '**PROFIL KELUARGA:**\nKeluarga menunjukkan komitmen kuat terhadap visi-misi sekolah, bertekad mendukung program pendidikan, serta proaktif dalam bekerja sama untuk membentuk Kayden menjadi anak yang beradab dan sholeh. Mereka mengakui dan bersedia mengatasi area perkembangan Kayden yang memerlukan stimulasi, terutama terkait regulasi emosi.\n\n**RINGKASAN INTI**: Kayden menunjukkan kemandirian dasar, preferensi belajar visual, serta bakat bercerita dengan konsentrasi baik. Namun, ia memerlukan pendampingan dalam regulasi emosi dan adaptasi sosial awal.\n**KESELARASAN**: 88%\n**POIN UTAMA**: Mandiri, Visual-Verbal, Konsentrasi Serius, Bakat Bercerita\n**RED FLAGS**: Regulasi emosi (marah/kesal), Adaptasi sosial awal (malu-malu)\n**REKOMENDASI SKOR**: 7.5/10', '2026-05-23 01:29:22.678'::timestamptz, '2026-05-23 01:29:22.678'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('3be956d5-6546-44f8-95b6-e218b2e6fe7a'::uuid, '49b5f135-4238-442b-9ce3-350a8499fe52'::uuid, '**RINGKASAN INTI**: Shofiyah adalah anak mandiri, supel, dan adaptif dengan fondasi ibadah sholat, namun memiliki tantangan konsentrasi belajar, minat baca, dan literasi Al-Qur''an, diperparah penggunaan gadget 3 jam/hari. Keluarga menunjukkan komitmen kuat terhadap pendidikan Islam modern, menyadari area stimulasi (fokus belajar), dan responsif terhadap perkembangan anak pasca riwayat speech delay.\n**KESELARASAN**: 90%\n**POIN UTAMA**: Sosialis-Mandiri, Fokus Singkat, Gadget Tinggi, Komitmen Keluarga Kuat\n**RED FLAGS**: Riwayat speech delay (3-4th), Penggunaan gadget (3 jam), Konsentrasi belajar, Ekspresi emosi (ngambeg/menangis)\n**REKOMENDASI SKOR**: 8/10', '2026-05-23 01:31:24.669'::timestamptz, '2026-05-23 01:31:24.669'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('d883ac30-4d13-4d9d-bb21-2acdb3c748c6'::uuid, '8a505330-5a54-47e2-a4d2-d26610e6b387'::uuid, '**RINGKASAN INTI**:\nJasmine menunjukkan kedisiplinan dasar (tidur teratur, tanggung jawab tugas) dan sikap hormat, didukung komitmen kuat orang tua terhadap pendidikan karakter Islam. Area pengembangan meliputi kemandirian ibadah, adaptasi lingkungan baru, regulasi emosi (cenderung diam saat kecewa), serta penguasaan mata pelajaran Matematika dan Bahasa Arab.\n\n**KESELARASAN**: Tidak dapat dinilai karena tidak tersedia data jawaban dari siswa untuk perbandingan.\n\n**POIN UTAMA**:\n*   Disiplin & Tanggung Jawab Tugas\n*   Potensi Religiusitas (PAI, Juz 30)\n*   Pengembangan Emosi & Akademik (Matematika, Arab)\n*   Dukungan Orang Tua Kuat\n\n**RED FLAGS**:\n*   Internalisasi emosi (diam saat marah/kecewa)\n*   Adaptasi lingkungan baru tidak cepat\n*   Perlu diingatkan untuk sholat\n\n**REKOMENDASI SKOR**: 7.5/10', '2026-05-23 01:33:57.792'::timestamptz, '2026-05-23 01:33:57.792'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('4a5598d8-08a1-4bea-bf13-b9dc4e78d6b9'::uuid, 'c8840975-d50f-4410-b8a4-b8e936cf2925'::uuid, '**Analisis Utama**: Terdapat ketidaksamaan yang signifikan antara jawaban Ratna dan orang tua, terutama pada aspek kedisiplinan ibadah (sholat), preferensi mata pelajaran, dan pertemanan, mengindikasikan perbedaan persepsi diri atau komunikasi dalam keluarga.\n\n**Persentase Keselarasan**: 65%\n\n**Kekuatan**:\n*   **Aktif Non-Akademik**: Memiliki prestasi di bidang beladiri jujitsu (sertifikat) dan menyukai olahraga (renang).\n*   **Ibadah & Al-Qur''an**: Rutin mengaji di rumah bersama orang tua, lancar membaca Al-Qur''an (juz 30), dan memiliki hafalan (surat An Naba).\n*   **Dukungan Keluarga**: Orang tua sangat mendukung program sekolah, bersedia bekerja sama, dan aktif dalam pendampingan (les, bicara dari hati ke hati).\n*   **Sikap Positif**: Secara umum bersikap sopan dan menghormati yang lebih tua, serta mampu menyelesaikan perbedaan pendapat dengan teman.\n\n**Red Flags/Perhatian**:\n*   **Kontradiksi Disiplin Ibadah**: Orang tua menyatakan Ratna masih perlu diingatkan untuk sholat 5 waktu, namun Ratna mengklaim selalu sholat tanpa diingatkan.\n*   **Persepsi Diri vs Realita Akademik**: Terjadi kontradiksi signifikan pada mata pelajaran favorit dan yang menjadi kendala/tidak disukai. Orang tua menyebut BHS Inggris sebagai kendala, sementara Ratna menyatakannya sebagai mata pelajaran yang disukai dan justru tidak menyukai MTK dan IPAS.\n*   **Kemampuan Adaptasi & Sosial**: Baik Ratna maupun orang tua menyebut Ratna memerlukan waktu lama untuk beradaptasi dan agak pemalu. Ratna juga menyatakan tidak memiliki teman dekat/kelompok main, kontradiktif dengan informasi orang tua yang menyebutkan ada teman dekat di sekolah dan les.\n*   **Rasa Percaya Diri & Pengambilan Keputusan**: Orang tua menyoroti area ini sebagai hal yang masih perlu bimbingan dan stimulasi.\n\n**Tanya Saat Wawancara**:\n1.  "Ratna, Ibu/Bapakmu menyampaikan kamu masih perlu diingatkan untuk sholat lima waktu. Bisakah kamu ceritakan bagaimana kebiasaan sholatmu di rumah?"\n2.  "Ada perbedaan pendapat tentang mata pelajaran yang kamu sukai dan yang menjadi kendala. Bisakah kamu ceritakan lebih detail, mata pelajaran mana yang paling membuatmu merasa tertantang dan mana yang paling kamu nikmati?"\n3.  "Kamu bilang tidak punya teman dekat, tapi orang tua menyebut kamu punya teman di sekolah dan di les. Bisakah kamu jelaskan lebih lanjut tentang pertemananmu dan apakah kamu merasa mudah berinteraksi?"\n\n**Skor Kesesuaian**: 6.5/10', '2026-05-09 02:55:35.916'::timestamptz, '2026-05-09 02:55:35.916'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('db3ec126-9aef-432a-a469-0fb215a9171b'::uuid, '40e820be-b3df-4720-aae0-160ec5311f46'::uuid, '**Analisis Utama**: Zafran menunjukkan potensi akademik yang baik, terutama di Matematika dan Bahasa Inggris, serta memiliki dasar agama yang cukup. Namun, terdapat perbedaan persepsi yang signifikan antara orang tua dan siswa terkait hobi, kebiasaan ibadah, dan kemandirian, serta tantangan besar pada motivasi dan tanggung jawab internal siswa.\n\n**Persentase Keselarasan**: 65%\n\n**Kekuatan**:\n*   Kecerdasan akademik di Matematika dan Bahasa Inggris.\n*   Aktif dan memiliki prestasi awal di bidang panahan (archery).\n*   Lancar membaca Al-Qur''an dan memiliki hafalan Juz 30 yang cukup.\n*   Sikap sopan dan menghargai terhadap yang lebih tua.\n*   Menerima teguran dan menyadari kesalahan.\n*   Dukungan orang tua sangat tinggi dan siap bekerja sama dengan sekolah.\n\n**Red Flags/Perhatian**:\n*   **Kontradiksi Informasi**: Ada ketidakselarasan signifikan antara jawaban orang tua dan siswa mengenai hobi, kebiasaan sholat (perlu diingatkan vs. tanpa diingatkan), ibadah sunnah, kemampuan adaptasi di lingkungan baru, serta kesediaan orang tua hadir di acara sekolah. Ini mengindikasikan kemungkinan perbedaan persepsi, komunikasi, atau tingkat kejujuran/kesadaran diri siswa.\n*   **Motivasi Internal**: Orang tua secara spesifik mencatat "motivasi" sebagai perhatian utama, menggambarkan Zafran sebagai sosok yang "pasrahan" dan "tidak mau ''lari'' untuk mengejar mimpinya", masih fokus pada bermain. Hal ini juga selaras dengan pengakuan siswa bahwa ia "belum mandiri & disiplin".\n*   **Tanggung Jawab & Kemandirian**: Meskipun orang tua menyatakan Zafran sudah terbiasa dengan tanggung jawab, ia sering lupa jika tidak diingatkan secara aktif, yang juga diakui siswa sebagai "belum mandiri & disiplin".\n*   **Adaptasi Lingkungan**: Orang tua menyatakan Zafran mudah beradaptasi, namun siswa menyatakan "tidak mudah bergaul/beradaptasi pada lingkungan baru".\n\n**Tanya Saat Wawancara**:\n1.  Zafran, orang tua kamu menyebut hobi kamu adalah Matematika, Bahasa Inggris, dan panahan, sementara kamu sendiri menyebut bidang seni. Bisakah kamu ceritakan lebih jauh tentang minat kamu di seni dan apakah kamu juga memiliki ketertarikan kuat pada Matematika, Bahasa Inggris, atau panahan?\n2.  Bagaimana kamu melihat dirimu sendiri dalam hal kemandirian dan motivasi belajar di SMP nanti? Menurutmu, hal apa yang paling perlu kamu tingkatkan?\n\n**Skor Kesesuaian**: 7/10', '2026-05-09 03:05:27.236'::timestamptz, '2026-05-09 03:05:27.236'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('f4d78ee0-306b-467d-8745-f9e75abccc84'::uuid, '9dade648-5a4c-46b5-8ece-ac22e2a87805'::uuid, '**Analisis Utama**: Teuku Rashya menunjukkan potensi non-akademik yang sangat menonjol di bidang olahraga, didukung oleh semangat berinteraksi dan adaptasi yang baik, namun terdapat perbedaan persepsi yang signifikan antara orang tua dan siswa terkait kemandirian dalam ibadah dan identifikasi tantangan akademik.\n\n**Persentase Keselarasan**: 76%\n\n**Kekuatan**:\n*   Prestasi non-akademik luar biasa di bidang sepak bola dan taekwondo, termasuk tingkat nasional dan internasional.\n*   Mudah bergaul, beradaptasi dengan lingkungan baru, serta memiliki sikap sopan dan baik dalam interaksi sosial.\n*   Memiliki hafalan Juz 30 Al-Qur''an dan keinginan kuat dari siswa serta orang tua untuk pendidikan Islam modern.\n*   Orang tua sangat mendukung dan berkomitmen untuk bekerja sama dengan sekolah.\n\n**Red Flags/Perhatian**:\n*   **Inkonsistensi dalam ibadah sholat 5 waktu dan kemandirian beribadah** (Ortu: perlu diingatkan; Siswa: kadang sholat, tapi merasa tidak perlu diingatkan).\n*   **Perbedaan persepsi yang kontras mengenai mata pelajaran kendala** (Ortu: Matematika; Siswa: tidak ada).\n*   **Level kemandirian dan disiplin diri** yang masih perlu dimonitor dan dikuatkan, terutama terkait inisiatif, tanggung jawab diri, dan konsistensi bangun pagi.\n*   **Kemampuan membaca Al-Qur''an** yang menurut ortu "masih belajar" sementara siswa mengklaim "lancar".\n*   Siswa menyatakan **tidak suka membaca buku**, berpotensi menjadi tantangan dalam proses belajar di SMP.\n\n**Tanya Saat Wawancara**:\n1.  "Teuku Rashya, ada perbedaan informasi antara kamu dan orang tua mengenai sholat 5 waktu dan perlunya diingatkan. Bisakah kamu ceritakan lebih jujur dan detail mengenai konsistensimu dalam sholat dan bagaimana kamu membangun kemandirian ibadahmu?"\n2.  "Orang tua kamu mengidentifikasi Matematika sebagai mata pelajaran yang sering menjadi kendala, namun kamu tidak merasa ada pelajaran yang sulit. Bisakah kamu jelaskan pandanganmu tentang Matematika dan bagaimana kamu mengelola kesulitan dalam mata pelajaran tersebut?"\n\n**Skor Kesesuaian**: 7.5/10', '2026-05-09 03:05:30.986'::timestamptz, '2026-05-09 03:05:30.986'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('08e8961d-63de-40e5-974b-38b56aa60b25'::uuid, '3327e485-4b6d-450a-ac79-3b13902d3e65'::uuid, '**Analisis Utama**: Terdapat kontradiksi signifikan antara jawaban orang tua dan calon siswa, terutama mengenai pelaksanaan ibadah sholat 5 waktu, sholat sunnah, kemampuan membaca Al-Qur''an, dan adaptasi lingkungan. Hal ini menimbulkan keraguan terhadap kejujuran siswa atau pemahaman orang tua mengenai kondisi anaknya.\n\n**Persentase Keselarasan**: 59%\n\n**Kekuatan**:\n*   Minat dan potensi prestasi di bidang olahraga (futsal juara 2).\n*   Ketertarikan pada mata pelajaran keagamaan (Tahfidz/Al-Qur''an Hadist).\n*   Sikap sopan santun terhadap yang lebih tua/guru.\n*   Keputusan sekolah di Al Fakhir merupakan keinginan mandiri siswa.\n*   Orang tua sangat mendukung program sekolah dan berharap besar pada peningkatan tanggung jawab sholat, hafalan, dan kemampuan akademik anak.\n\n**Red Flags/Perhatian**:\n*   **Kontradiksi kritis** pada aspek fundamental agama:\n    *   Sholat 5 waktu (Ortu: Tidak, hanya Maghrib; Siswa: Ya).\n    *   Sholat tanpa diingatkan (Ortu: Tersirat tidak; Siswa: Ya).\n    *   Sholat sunnah (Ortu: Tidak; Siswa: Ya).\n    *   Lancar membaca Al-Qur''an (Ortu: Belum; Siswa: Ya).\n*   **Perbedaan signifikan** persepsi kemampuan beradaptasi dengan lingkungan baru (Ortu: Iya; Siswa: Tidak).\n*   Jawaban siswa yang tidak lazim terkait penanganan perbedaan pendapat ("berkenalan").\n*   Kecenderungan mengeluh saat menghadapi tugas sulit/menumpuk (menurut orang tua).\n*   Tidak adanya pendampingan belajar di rumah.\n*   Perbedaan informasi mengenai urutan anak dalam keluarga (Ortu: ke-4; Siswa: ke-5).\n\n**Tanya Saat Wawancara**:\n*   "Muhammad, orang tua kamu menyebutkan kamu belum sholat 5 waktu secara konsisten dan belum lancar membaca Al-Qur''an. Apakah ini benar, atau ada perkembangan terbaru yang bisa kamu ceritakan?"\n*   "Kamu bilang tidak mudah beradaptasi dengan lingkungan baru. Bisa jelaskan lebih lanjut mengapa dan bagaimana kamu menghadapinya, serta apa yang kamu harapkan dari lingkungan sekolah baru?"\n*   "Apa yang kamu maksud dengan ''berkenalan'' ketika ada perbedaan pendapat dengan teman?"\n\n**Skor Kesesuaian**: 4/10', '2026-05-09 03:25:47.124'::timestamptz, '2026-05-09 03:25:47.124'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('7593128b-f9ca-4ebc-a3e9-6cc4ac016693'::uuid, '6a7957b7-a983-441a-b7c5-269c16db3249'::uuid, '**Analisis Utama**: Latifa menunjukkan keselarasan tinggi antara jawaban orang tua dan dirinya mengenai kepribadian, ibadah, dan minat akademik, menunjukkan pemahaman diri dan konsistensi informasi. Namun, terdapat inkonsistensi data mengenai struktur keluarga (status bersaudara dan keberadaan adik) yang perlu klarifikasi lebih lanjut.\n\n**Persentase Keselarasan**: 95% (Hampir semua poin yang dapat dibandingkan selaras, meskipun terdapat satu inkonsistensi internal pada jawaban kedua belah pihak terkait status bersaudara.)\n\n**Kekuatan**:\n*   Sangat baik dalam ibadah: Sholat 5 waktu tanpa diingatkan, puasa sunnah, lancar membaca dan memiliki hafalan Al-Qur''an 1 juz.\n*   Kemandirian dan tanggung jawab tinggi: Persepsi diri dan orang tua selaras, selalu berusaha mencari solusi untuk tugas sulit.\n*   Sikap sosial positif: Menghormati orang lebih tua/muda, mudah beradaptasi, menghargai perbedaan pendapat dengan teman dan guru.\n*   Motivasi belajar internal: Memilih sekolah atas keinginan sendiri, menyukai Bahasa Inggris dan Sejarah, serta gemar membaca buku sejarah.\n*   Memiliki prestasi di SD ("Star of the Month").\n*   Orang tua sangat mendukung dan bersedia bekerja sama dengan pihak sekolah.\n\n**Red Flags/Perhatian**:\n*   **Inkonsistensi data keluarga**: Baik orang tua maupun siswa menyatakan "anak pertama dari 1 bersaudara" namun sama-sama menyebutkan akrab dengan "adik".\n*   **Ketidaktahuan pekerjaan orang tua**: Siswa menyatakan "Tidak tahu" pekerjaan Bapak/Ibu.\n*   **Pengelolaan emosi**: Orang tua menyebutkan Latifa "Hanya diam" saat marah atau kecewa.\n*   **Mata pelajaran kendala**: Matematika diidentifikasi sebagai mata pelajaran sulit oleh Latifa dan orang tua.\n\n**Tanya Saat Wawancara**:\n*   Mohon klarifikasi mengenai struktur keluarga Latifa (apakah ada adik kandung, tiri, atau keluarga lain yang dianggap adik)?\n*   Bagaimana Latifa mengelola perasaannya lebih jauh saat marah atau kecewa selain hanya diam?\n*   Bagaimana strategi yang sudah atau akan dilakukan Latifa dan orang tua untuk mengatasi kendala di mata pelajaran Matematika?\n\n**Skor Kesesuaian**: 8/10 (Profil kuat dalam aspek spiritual, sosial, dan motivasi belajar, namun ada beberapa area yang memerlukan klarifikasi dan perhatian, terutama inkonsistensi data keluarga dan cara pengelolaan emosi.)', '2026-05-09 00:19:23.666'::timestamptz, '2026-05-09 00:19:23.666'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('7b6a1682-f105-48fc-b3a9-0acf957aa818'::uuid, 'c58930c7-b943-4dab-a3a6-157149f9d35a'::uuid, '**Analisis Utama**: Terdapat ketidakselarasan signifikan antara persepsi orang tua dan siswa mengenai kemandirian, ketaatan beribadah, dan pencapaian hafalan Al-Qur''an, mengindikasikan perbedaan pemahaman atau tingkat kesadaran.\n**Persentase Keselarasan**: 58%\n**Kekuatan**:\n*   Siswa memiliki minat kuat di Matematika dan hobi Sepakbola.\n*   Cukup adaptif dengan lingkungan baru dan interaksi sosial yang baik (menghormati yang lebih tua/muda, mengalah dalam perbedaan pendapat).\n*   Orang tua sangat suportif dan berkomitmen untuk bekerja sama dengan sekolah.\n**Red Flags/Perhatian**:\n*   **Kontradiksi signifikan** antara orang tua dan siswa mengenai kepemilikan/penggunaan gadget, kemandirian sholat 5 waktu, pelaksanaan ibadah sunnah, serta jumlah hafalan Al-Qur''an (Juz 30 vs Belum).\n*   **Perbedaan persepsi** terkait kemandirian dan kedisiplinan siswa (orang tua: perlu dibimbing/diingatkan; siswa: sudah mandiri & disiplin).\n*   **Minat membaca**: Orang tua menilai minat membaca kurang, sementara siswa mengklaim suka membaca buku cerita.\n*   **Kondisi kesehatan**: Riwayat alergi dingin dan 2x operasi perlu menjadi perhatian.\n*   Siswa belum memiliki prestasi yang dapat disebutkan secara spesifik.\n*   "Rasa memiliki" masih perlu dikuatkan.\n**Tanya Saat Wawancara**:\n1.  Mohon klarifikasi mengenai penggunaan gadget dan status hafalan Al-Qur''an Muhammad Adhyasta saat ini, karena terdapat perbedaan informasi.\n2.  Bagaimana strategi bersama antara orang tua dan sekolah untuk membangun kemandirian Adhyasta, terutama dalam ibadah dan tanggung jawab harian?\n**Skor Kesesuaian**: 5.5/10', '2026-05-09 03:51:33.567'::timestamptz, '2026-05-09 03:51:33.567'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('2054e9ca-cbce-4e4c-9e67-8e3a2cc84fea'::uuid, '861bec24-e9c0-47ca-bc13-df0cc3768028'::uuid, 'Berikut ringkasan evaluasi untuk Gendhis Ayuningtyas:\n\n**Analisis Utama**: Gendhis Ayuningtyas adalah calon siswa SMP yang diidentifikasi berkebutuhan khusus oleh orang tua, menunjukkan kebutuhan pendampingan intensif dengan keselarasan informasi yang moderat antara jawaban orang tua dan siswa, terutama terkait kemandirian, ibadah, dan minat belajar.\n\n**Persentase Keselarasan**: 50%\n\n**Kekuatan**:\n*   Dukungan penuh dan komitmen tinggi dari orang tua terhadap program sekolah dan partisipasi aktif.\n*   Pengakuan diri (siswa) dan orang tua akan pentingnya bimbingan untuk kemandirian, disiplin, dan ibadah.\n*   Memiliki minat di bidang seni (mewarnai/gambar).\n*   Sikap baik dan penurut terhadap guru (menurut orang tua).\n*   Keluarga proaktif dalam pendampingan belajar dan bermain di rumah.\n\n**Red Flags/Perhatian**:\n*   **Catatan Kebutuhan Khusus**: Ananda diidentifikasi berkebutuhan khusus oleh orang tua, yang memerlukan perhatian dan pendekatan pendidikan yang disesuaikan.\n*   Ketidakselarasan informasi yang signifikan antara siswa dan orang tua pada beberapa aspek kunci (misal: anak ke berapa, hobi, mata pelajaran favorit/sulit, teman dekat, persepsi prestasi, dan interaksi sosial).\n*   Kemandirian dan kedisiplinan yang masih sangat rendah, baik dalam kehidupan sehari-hari maupun ibadah (salat 5 waktu, sunah, mengaji).\n*   Respon emosional cenderung "ngambek" atau menangis saat menghadapi kesulitan atau ditegur.\n*   Kesulitan adaptasi dengan lingkungan baru tanpa pendampingan.\n*   Minat belajar cenderung rendah (tidak suka membaca buku, mata pelajaran disukai "mewarnai" di jenjang SMP).\n\n**Tanya Saat Wawancara**:\n*   "Mohon dijelaskan lebih lanjut mengenai kebutuhan khusus Gendhis dan bentuk pendampingan spesifik yang diharapkan dari sekolah."\n*   "Gendhis, ada beberapa perbedaan informasi antara jawabanmu dan orang tua. Bisakah kamu ceritakan tentang hobi dan mata pelajaran yang paling kamu suka dan tidak suka?"\n\n**Skor Kesesuaian**: 5/10 (Mengingat Gendhis memiliki kebutuhan khusus dan tingkat kemandirian serta kedisiplinan yang rendah, penyesuaian kurikulum dan fasilitas mungkin diperlukan agar sesuai dengan lingkungan SMP Islam Modern Al Fakhir. Dukungan orang tua yang sangat tinggi menjadi nilai positif, namun tantangan yang ada cukup signifikan.)', '2026-05-09 04:16:30.297'::timestamptz, '2026-05-09 04:16:30.297'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('4a9dc1bf-434c-4ee7-b854-7077ab272312'::uuid, 'b1ddc9f9-221a-47f0-a60d-8588375b902c'::uuid, '**RINGKASAN INTI**: Raden Roro Chaira Luna Kusuma Wardani menunjukkan potensi akademik dan non-akademik yang baik, serta kesiapan untuk mandiri; namun, terdapat diskrepansi signifikan antara persepsi orang tua dan siswa mengenai konsistensi ibadah, hafalan Al-Qur''an, dan adaptasi terhadap lingkungan baru.\n\n**KESELARASAN**: 61%\n**POIN UTAMA**: Prestasi Unggul, Mandiri, Perlu Konsistensi Ibadah, Adaptasi Bertahap.\n**RED FLAGS**: Discrepansi data ibadah (hafalan, sholat), konsistensi aturan rumah, dan adaptasi lingkungan antara ortu dan siswa. Perlu penguatan adab/etika.\n**REKOMENDASI SKOR**: 7.5/10', '2026-05-19 03:33:08.056'::timestamptz, '2026-05-19 03:33:08.056'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('27d39870-e9bc-49d8-8ecc-21b1b9e8ecfb'::uuid, 'cf42c3eb-85e4-4f97-9560-63085cc0920a'::uuid, '**RINGKASAN INTI**: Aldafi menunjukkan kemandirian dasar baik, fondasi agama kuat, serta adaptif dan sopan dalam interaksi sosial. Keluarga sangat berkomitmen pada pendidikan seimbang, mengamati Aldafi sebagai pembelajar visual-kinestetik, dan aktif mendukung perkembangannya.\n\n**KESELARASAN**: 95%\n**POIN UTAMA**: Kemandirian, Fondasi Agama, Adaptif Sosial, Dukungan Keluarga\n**RED FLAGS**: Pengelolaan emosi\n**REKOMENDASI SKOR**: 8.5/10', '2026-05-23 00:48:51.04'::timestamptz, '2026-05-23 00:48:51.04'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('17e505bd-0a02-4c98-982c-1c039d7ce5a2'::uuid, '58b847ed-dda5-4a13-920d-aab983cc7728'::uuid, '**RINGKASAN INTI**: Adiba menunjukkan kemandirian dasar, minat di bidang seni (menyanyi/menari), dan kemampuan mengikuti instruksi sederhana. Namun, perlu stimulasi signifikan pada konsentrasi, adaptasi lingkungan baru, regulasi emosi, serta fondasi akademik dasar dan keagamaan.\n\n**KESELARASAN**: 90% (Orang tua menunjukkan kesadaran tinggi atas kekuatan dan area pengembangan anak, serta komitmen kuat terhadap pendidikan dan kolaborasi dengan sekolah.)\n\n**POIN UTAMA**: Mandiri Dasar, Minat Seni, Regulasi Emosi, Fondasi Akademik\n\n**RED FLAGS**: Emosi belum stabil (mudah marah/ngambek), kurang konsentrasi/adaptasi lingkungan, fondasi akademik & keagamaan dasar lemah.\n\n**REKOMENDASI SKOR**: 6.5/10', '2026-05-23 00:50:42.779'::timestamptz, '2026-05-23 00:50:42.779'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('34fa0976-0d7e-404f-84c3-d171a012dd9b'::uuid, 'd53acdd2-1ffc-4043-abe2-a5d41a5995ff'::uuid, 'Berikut ringkasan evaluasi untuk Muhammad Khafid Putra Nasution:\n\n**RINGKASAN INTI**: Muhammad Khafid menunjukkan potensi adaptasi sosial yang baik, kepatuhan terhadap aturan, serta dukungan penuh dari orang tua dalam pendidikan. Namun, ia perlu penguatan kemandirian dalam ibadah, kelancaran membaca Al-Qur''an, serta pengembangan disiplin dan kepercayaan diri.\n\n**KESELARASAN**: Tidak ada data pembanding dari siswa (asumsi seluruh data berasal dari orang tua).\n\n**POIN UTAMA**:\n*   Sosial adaptif\n*   Dukungan ortu kuat\n*   Disiplin & PD perlu\n*   Literasi Al-Qur''an\n\n**RED FLAGS**:\n*   Ekspresi emosi cenderung internal (diam/menyendiri saat marah/kecewa).\n*   Kemandirian ibadah (sholat masih perlu diingatkan).\n*   Kelancaran membaca Al-Qur''an belum optimal.\n\n**REKOMENDASI SKOR**: 8/10', '2026-05-23 00:51:03.283'::timestamptz, '2026-05-23 00:51:03.283'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('2ef82295-39be-42bf-89ae-a0acb24d3a79'::uuid, '1b40a08b-6311-4cbe-a41e-e5bbd6769ea2'::uuid, '**RINGKASAN INTI**: Muhammad Rafid Mazayya memiliki pondasi kuat dalam hafalan Al-Qur''an (Juz 28) dan minat olahraga (futsal), didukung oleh adaptabilitas sosial dan kepatuhan terhadap aturan rumah. Perlu pengembangan kemandirian ibadah, keberanian mengemukakan pendapat, dan optimalisasi keterampilan kepemimpinan serta pengelolaan emosi.\n\n**KESELARASAN**: N/A (Data jawaban siswa tidak tersedia untuk perbandingan langsung dengan jawaban orang tua).\n\n**POIN UTAMA**:\n1.  Hafiz Juz 28 & Olahraga (Futsal)\n2.  Disiplin Rumah & Adaptif\n3.  Penguatan Leadership & Ibadah\n\n**RED FLAGS**:\n*   Ibadah sholat perlu pengingat.\n*   Terkadang membantah saat ditegur.\n*   Perlu stimulus leadership dan bicara di depan umum.\n\n**REKOMENDASI SKOR**: 8/10', '2026-05-23 01:04:36.087'::timestamptz, '2026-05-23 01:04:36.087'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('6bfb252b-eb2e-48df-a24e-b3f92278fbc7'::uuid, '007717e5-4520-4db9-9c7a-c7f3b7d0721f'::uuid, '**RINGKASAN INTI**: Hawwari menunjukkan kebutuhan tinggi terhadap pendampingan dalam kemandirian, tanggung jawab, dan pengembangan kepercayaan diri, diperparah oleh kecenderungan introvert dan tantangan literasi. Meskipun aktif secara fisik dan didukung orang tua, ia memerlukan stimulasi intensif untuk adaptasi, komunikasi emosi, dan konsistensi dalam aturan.\n\n**KESELARASAN**: Data berasal sepenuhnya dari perspektif orang tua; tidak ada data siswa untuk perbandingan langsung. Namun, keselarasan antara identifikasi tantangan perkembangan anak (kemandirian, percaya diri, komunikasi, tanggung jawab) dan harapan serta alasan pemilihan sekolah sangat tinggi (95%), menunjukkan kesadaran dan komitmen orang tua.\n\n**POIN UTAMA**:\n*   Kemandirian & Tanggung Jawab Rendah\n*   Introvert & Komunikasi Emosi\n*   Percaya Diri & Literasi Perlu Stimulasi\n*   Konsistensi Aturan & Penerimaan Teguran\n\n**RED FLAGS**:\n*   Kesulitan menerima teguran.\n*   Ekspresi emosi (menangis, nada tinggi saat marah/kecewa).\n*   Inkonsisten terhadap aturan rumah.\n\n**REKOMENDASI SKOR**: 6/10', '2026-05-23 01:34:07.889'::timestamptz, '2026-05-23 01:34:07.889'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('11d6f0b0-e317-4a49-8e46-e2de62e6a8d5'::uuid, '807a2c56-31e6-49b5-8087-a415b0edcfba'::uuid, '**RINGKASAN INTI**: Muhammad Adha menunjukkan potensi sosial dan spiritual yang kuat serta kemudahan beradaptasi. Namun, ia memiliki tantangan dalam fokus belajar dan regulasi emosi saat menghadapi kesulitan, serta kemandirian yang masih perlu distimulasi.\n\n**KESELARASAN**: 90%\n\n**POIN UTAMA**:\n*   Adaptif & Sopan\n*   Dasar Agama Baik\n*   Perlu Stimulasi Belajar\n*   Kemandirian Terbatas\n\n**RED FLAGS**: Respon marah/melempar saat kesulitan belajar; konsentrasi terganggu jika materi membosankan.\n\n**REKOMENDASI SKOR**: 8/10', '2026-05-23 01:45:36.977'::timestamptz, '2026-05-23 01:45:36.977'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('ccc60d68-f3b8-4215-94bc-76d4e8f9bf8a'::uuid, '285edaa0-1de1-4c04-9bfb-f3ddf6e2c07d'::uuid, '**RINGKASAN INTI**: Prisia menunjukkan kemandirian belajar, kreativitas desain, dan adaptasi sosial yang baik, didukung minat baca serta kemampuan berbahasa Inggris yang menonjol. Keluarga sangat kooperatif, berorientasi pada pengembangan holistik, dan selaras dengan visi sekolah.\n**KESELARASAN**: 95%\n**POIN UTAMA**: Pembelajar Mandiri, Kreativitas Desain, Adaptasi Sosial, Minat Bahasa/Baca\n**RED FLAGS**: Regulasi emosi (baperan/cengeng), konsentrasi (kontekstual), konsistensi instruksi.\n**REKOMENDASI SKOR**: 9/10', '2026-05-23 01:47:36.137'::timestamptz, '2026-05-23 01:47:36.137'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('52916d69-710f-4135-bc4e-d291ccc217fe'::uuid, 'e8e49df6-a94a-4007-b5a3-34db18d1ef46'::uuid, 'Berikut ringkasan evaluasi untuk Nayla Anindya Tirtadinata:\n\n**RINGKASAN INTI**: Nayla menunjukkan kemandirian dasar, minat seni (menari), serta fondasi agama dan akademik yang baik, didukung keluarga berkomitmen. Adaptasi awal dan regulasi emosi menjadi area fokus pengembangan.\n**KESELARASAN**: 90%\n**POIN UTAMA**: Mandiri, Minat Seni, Keluarga Komitmen, Area Pengembangan Emosi\n**RED FLAGS**: Regulasi emosi (catatan orang tua)\n**REKOMENDASI SKOR**: 8.5/10', '2026-05-23 01:54:31.735'::timestamptz, '2026-05-23 01:54:31.735'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('90e8a1bf-d05d-4af7-ab00-918314d0d069'::uuid, '9e7ebc95-6804-4b26-a1f2-7d9f018c6d94'::uuid, '**RINGKASAN INTI**: Umar, seorang anak tunggal dengan kondisi ASD Level 1, menunjukkan profil belajar visual-kinestetik, kemampuan dasar yang baik namun perlu stimulasi pada konsentrasi dan interaksi sosial. Orang tua sangat menyadari kebutuhan khusus Ananda dan berkomitmen penuh pada pendidikan interaktif untuk kemandiriannya.\n**KESELARASAN**: 90%\n**POIN UTAMA**: ASD Level 1, Visual-Kinestetik, Sosialisasi/Konsentrasi, Kemandirian Ibadah.\n**RED FLAGS**: ASD Level 1, Keterbatasan Komunikasi/Sosialisasi, Konsentrasi Rendah.\n**REKOMENDASI SKOR**: 7.0/10', '2026-05-23 03:08:13.84'::timestamptz, '2026-05-23 03:08:13.84'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('3dd11252-c914-434c-b8f9-bf6c6da173fc'::uuid, 'f8897b60-2693-4ac9-9b34-b4ac998c754b'::uuid, '**RINGKASAN INTI**: Sakheena menunjukkan kemandirian dasar yang baik, disiplin waktu, serta minat belajar visual dengan bakat berhitung dan bercerita. Keluarga sangat suportif, berorientasi nilai Islam modern, dan berkomitmen tinggi terhadap pendidikan anak.\n**KESELARASAN**: 93%\n**POIN UTAMA**: Mandiri, Visual Learner, Bakat Bercerita/Berhitung, Keluarga Suportif\n**RED FLAGS**: Nihil\n**REKOMENDASI SKOR**: 9/10', '2026-05-23 03:33:26.153'::timestamptz, '2026-05-23 03:33:26.153'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('06d8f84e-868b-4fe7-b59e-7ee6eb7e96c0'::uuid, '5b075187-5374-4a44-9f45-8f3fb33aadd6'::uuid, '**RINGKASAN INTI**: Nusaibah menunjukkan kemandirian dasar yang baik, memiliki fondasi agama, dan adaptif, namun memerlukan stimulasi lebih lanjut dalam membaca dan konsentrasi. Keluarga sangat suportif, berkomitmen pada visi sekolah, dan siap bekerja sama erat dalam perkembangan anak.\n**KESELARASAN**: 93%\n**POIN UTAMA**: Mandiri, Religius, Keluarga Aktif, Adaptif\n**RED FLAGS**: Nihil\n**REKOMENDASI SKOR**: 8.5/10', '2026-05-23 04:17:52.643'::timestamptz, '2026-05-23 04:17:52.643'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('6de2b38c-132e-4313-a0c6-d96b7d960716'::uuid, 'fedd1469-38fa-403d-b2d3-e8692290855e'::uuid, '**RINGKASAN INTI**: Tynov Naufal Eryus adalah calon siswa yang mandiri, bertanggung jawab, disiplin dalam ibadah, serta memiliki adaptasi sosial yang baik, didukung penuh oleh keluarga yang aktif. Ia menunjukkan kesiapan tinggi untuk tuntutan belajar SMP, dengan kekuatan non-akademik dan dasar spiritual kuat.\n\n**KESELARASAN**: Tidak Tersedia (Data jawaban siswa tidak disertakan)\n\n**POIN UTAMA**: Mandiri, Religius, Adaptif, Dukungan Keluarga Kuat\n\n**RED FLAGS**: Keberanian tampil (perlu stimulasi), Matematika (kendala mata pelajaran)\n\n**REKOMENDASI SKOR**: 9/10', '2026-06-12 01:15:11.974'::timestamptz, '2026-06-12 01:15:11.974'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('9a405f0b-0ab5-48e9-943a-e9d60fafad30'::uuid, '2000671e-7188-4dd4-957e-8f5bd8b0f6f0'::uuid, '**RINGKASAN INTI**: Ray adalah calon siswa mandiri, disiplin, religius (Al-Qur''an lancar, hafalan >10 surat), dan fokus belajar dengan minat kuat pada konstruksi/seni. Keluarga menunjukkan komitmen tinggi, sangat suportif, dan aktif dalam mendukung tumbuh kembang serta kolaborasi dengan sekolah.\n\n**KESELARASAN**: 95%\n\n**POIN UTAMA**:\n1.  Mandiri & Religius\n2.  Fokus Belajar & Minat Konstruksi/Seni\n3.  Keluarga Sangat Suportif\n4.  Perlu Stimulasi Emosi (Menerima Kritik)\n\n**RED FLAGS**: Sulit menerima kritikan; Perlu stimulasi kontrol emosi.\n\n**REKOMENDASI SKOR**: 9/10', '2026-06-12 01:16:49.207'::timestamptz, '2026-06-12 01:16:49.207'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('421d65c2-df7c-4ddf-8ac2-0765a2c4cb51'::uuid, '963405b0-dc99-41ce-a1bc-604e59ec6c05'::uuid, '**RINGKASAN INTI**: Fatah Aldizar Ahsan menunjukkan kemandirian tinggi, kedisiplinan terstruktur, dan adaptasi sosial yang sangat baik, didukung pola asuh keluarga yang konsisten. Ia memiliki minat kuat pada seni dan membaca, dengan dasar agama yang baik, namun memerlukan perhatian khusus terkait alergi udara dan potensi kejang akibat kelelahan/suhu badan.\n**KESELARASAN**: 95%\n**POIN UTAMA**: Disiplin, Mandiri, Adaptif, Perhatian Kesehatan\n**RED FLAGS**: Alergi udara (debu), risiko kejang jika terlalu capek/suhu >37°C.\n**REKOMENDASI SKOR**: 9/10', '2026-06-12 01:24:56.016'::timestamptz, '2026-06-12 01:24:56.016'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('43140de6-3a3a-4150-bdad-e6c3e00e0e55'::uuid, '29c4584f-c694-4fe2-a0db-b06624998a06'::uuid, '**RINGKASAN INTI**: Darrel Saviyan Altezza menunjukkan kemandirian kuat, kecerdasan dasar sangat baik, dan adaptasi sosial yang tinggi. Namun, ia memerlukan stimulasi dalam regulasi emosi dan mempertahankan konsentrasi.\n**KESELARASAN**: 88%\n**POIN UTAMA**: Mandiri, Adaptif, Potensial Akademik, Kritis-Analitis\n**RED FLAGS**: Regulasi emosi, konsentrasi, kecenderungan usil\n**REKOMENDASI SKOR**: 8.5/10\n\n---\n**PROFIL KELUARGA:**\nKeluarga menunjukkan komitmen tinggi terhadap pendidikan Islami dan perkembangan anak sesuai visi-misi sekolah. Dukungan aktif dan kesediaan bekerja sama dengan sekolah sangat kuat, dengan kesadaran akan area stimulasi yang masih dibutuhkan Ananda. Fokus pada pembentukan karakter dan kecerdasan menjadi prioritas utama orang tua.', '2026-06-12 01:30:59.936'::timestamptz, '2026-06-12 01:30:59.936'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('494c0395-ddd9-470d-8eb6-6c44b3973d96'::uuid, 'f29bf112-ee9a-4e70-8dd0-48180390c66a'::uuid, '**RINGKASAN INTI**: Alfian Kafie Firdaus menunjukkan potensi seni dan akuntabilitas sosial dasar. Namun, terdapat inkonsistensi data signifikan antara siswa dan orang tua mengenai kemandirian, kedisiplinan ibadah, adaptasi sosial, dan motivasi belajar.\n\n**KESELARASAN**: 59% (Reliabilitas data antara siswa dan orang tua rendah, menunjukkan perbedaan persepsi atau informasi).\n\n**POIN UTAMA**:\n1.  Disparitas Persepsi\n2.  Ibadah & Kemandirian\n3.  Motivasi Akademik\n4.  Adaptasi Sosial\n\n**RED FLAGS**:\n1.  **Kontradiksi Data Signifikan**: Terutama terkait ibadah (sholat sunnah, tanpa diingatkan), minat belajar (pelajaran disukai/tidak disukai), adaptasi sosial, dan catatan prestasi.\n2.  **Ketergantungan**: Terlihat pada tugas sekolah (minta bantuan orang tua) dan kekhawatiran pribadi (takut tidur sendiri).\n3.  **Motivasi Belajar**: Pengakuan siswa "kurang suka belajar" dan ketidakpastian minat mata pelajaran (menurut orang tua).\n4.  **Uang Saku Tinggi**: Nominal Rp 50.000/hari berpotensi isu gaya hidup.\n5.  **Pilihan Sekolah**: Atas keinginan orang tua, bukan siswa.\n\n**REKOMENDASI SKOR**: 6/10', '2026-06-23 00:31:55.188'::timestamptz, '2026-06-23 00:31:55.188'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('2f2d0919-b4cd-4f3b-98fe-ce6006741d3c'::uuid, 'a6cab318-d55f-4249-98fb-660b1aeb8b44'::uuid, '**RINGKASAN INTI**: Earlyta menunjukkan potensi akademik (Sains) dan seni (gitar/gambar), fasih Al-Qur''an (Juz 30), serta adaptif. Namun, terdapat inkonsistensi data antara siswa dan orang tua terkait disiplin ibadah dan kemandirian, yang diakui orang tua masih memerlukan penguatan dan kontrol waktu gadget.\n\n**KESELARASAN**: 68%\n\n**POIN UTAMA**:\n*   Potensi Akademik & Seni\n*   Fasih Al-Qur''an\n*   Adaptif & Sopan\n*   Disiplin Berproses\n\n**RED FLAGS**:\n*   Inkonsistensi data (disiplin ibadah, prestasi, kemandirian)\n*   Disiplin dan tanggung jawab masih sering diingatkan (pengakuan ortu)\n*   Kontrol penggunaan gadget belum konsisten\n\n**REKOMENDASI SKOR**: 7/10', '2026-06-23 01:02:54.471'::timestamptz, '2026-06-23 01:02:54.471'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('2e9d6a3a-2e3b-4247-ad60-24e1fc39620f'::uuid, 'e189d094-4966-4137-9354-b3c7e0a8741a'::uuid, '**RINGKASAN INTI**:\nTalyssa memiliki fondasi religius yang cukup baik (hafalan 1 juz, puasa sunnah) namun menunjukkan tantangan signifikan dalam kemandirian, adaptasi sosial, dan ekspresi diri. Terdapat disparitas nyata antara persepsi siswa dan orang tua terkait kemandirian, kedisiplinan, serta kesediaan orang tua berpartisipasi aktif dalam kegiatan sekolah.\n\n**KESELARASAN**: 47%\n\n**POIN UTAMA**:\n1.  Religiusitas Terjaga\n2.  Tantangan Adaptasi Sosial\n3.  Kemandirian Perlu Stimulasi\n4.  Disparitas Persepsi Data\n\n**RED FLAGS**:\nDisparitas signifikan antara persepsi siswa dan orang tua (kemandirian, disiplin sholat, adaptasi lingkungan baru, partisipasi orang tua di sekolah); Siswa secara eksplisit menyatakan "tidak mudah bergaul/beradaptasi" dan "susah bergaul" sebagai kekurangan.\n\n**REKOMENDASI SKOR**: 6/10', '2026-06-23 01:49:48.713'::timestamptz, '2026-06-23 01:49:48.713'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('031e750b-a523-4187-baae-3f46eafe598d'::uuid, '1a58f6fc-7243-4b36-b974-8ae21d9c9a7e'::uuid, 'Berikut ringkasan evaluasi untuk Azka Al Farabi:\n\n**RINGKASAN INTI**: Azka menunjukkan potensi akademik yang baik (Matematika, hafalan Juz 30) namun memerlukan penguatan signifikan dalam kemandirian, regulasi emosi, dan adaptasi sosial. Kondisi kesehatan Sindrom Nefrotik yang sedang diobati membutuhkan perhatian khusus dan pemantauan.\n\n**KESELARASAN**: Data yang tersedia berasal dari satu sumber (perspektif orang tua mengenai siswa), sehingga perbandingan langsung antara jawaban orang tua dan siswa tidak dapat dilakukan.\n\n**POIN UTAMA**:\n*   Potensi Akademik & Qur''an\n*   Kemandirian & Regulasi Emosi\n*   Adaptasi Sosial (Perlu Stimulasi)\n*   Kondisi Medis (Ginjal)\n\n**RED FLAGS**:\n*   Riwayat Sindrom Nefrotik (Ginjal bocor), sedang dalam pengobatan.\n*   Regulasi emosi dan konsistensi terhadap aturan rumah masih bergantung pada mood.\n*   Kecenderungan bergantung pada orang tua saat menghadapi tugas sulit dan perlu diingatkan untuk sholat.\n\n**REKOMENDASI SKOR**: 6.5/10', '2026-06-24 01:49:19.44'::timestamptz, '2026-06-24 01:49:19.44'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('650bef53-284b-4c6c-bd2c-8eb847b55591'::uuid, 'fdda75ee-edf2-4bdd-8208-d2db3e36f842'::uuid, '**RINGKASAN INTI**: Jasmine menunjukkan kemandirian personal dan kesiapan akademik dasar yang baik, didukung fondasi agama kuat serta rutinitas keluarga terstruktur. Area pengembangan utama adalah stimulasi keberanian bersosialisasi dan ekspresi diri.\n**KESELARASAN**: 95%\n**POIN UTAMA**: Kemandirian tinggi, Dasar agama kuat, Potensi seni/bahasa, Perlu stimulasi keberanian\n**RED FLAGS**: Pemalu, kurang berani berbicara/tampil.\n**REKOMENDASI SKOR**: 9/10', '2026-06-30 01:30:10.459'::timestamptz, '2026-06-30 01:30:10.459'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('4324d015-6411-4692-8181-14e8c3b01bd2'::uuid, '46cce629-da1b-4c15-8862-475b4397efd0'::uuid, '**PROFIL KELUARGA**: Keluarga menunjukkan keseriusan dan komitmen tinggi terhadap pendidikan agama serta sosial Fawwaz, dengan harapan besar pada pengembangan komunikasi dan sosialisasi anak di sekolah. Mereka aktif mengidentifikasi area stimulasi yang diperlukan.\n\n**RINGKASAN INTI**: M. Fawwaz memiliki kemandirian dasar dan kepatuhan ibadah yang baik, namun memerlukan stimulasi intensif pada komunikasi, sosialisasi, serta minat belajar dan membaca.\n\n**KESELARASAN**: 88%\n**POIN UTAMA**: Kemandirian, Kepatuhan, Komunikasi, Sosialisasi\n**RED FLAGS**: Komunikasi lemah, Sosialisasi kurang, Minat baca/belajar rendah, Cenderung pasif.\n**REKOMENDASI SKOR**: 6.5/10', '2026-06-30 01:37:11.331'::timestamptz, '2026-06-30 01:37:11.331'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('06e3dd84-1707-4c83-8cda-bf0860838da7'::uuid, '45621fef-5cd8-444a-a665-d2e19bcdfd3e'::uuid, '**RINGKASAN INTI**: Daffa menunjukkan kemandirian dasar, potensi mengikuti instruksi, dan memiliki bekal religiusitas awal, namun memerlukan stimulasi fokus belajar, minat baca, dan pendampingan adaptasi lingkungan baru. Keluarga menunjukkan komitmen kuat terhadap pendidikan agama dan modern, serta sangat bersedia berkolaborasi.\n**KESELARASAN**: 95%\n**POIN UTAMA**: Kemandirian Awal, Perhatian Detail, Fokus & Minat Baca, Komitmen Keluarga Kuat\n**RED FLAGS**: Mudah Terdistraksi, Minat Baca Rendah, Durasi Gadget Tinggi, Adaptasi Lingkungan (struggle)\n**REKOMENDASI SKOR**: 8/10', '2026-07-04 02:06:41.811'::timestamptz, '2026-07-04 02:06:41.811'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;
INSERT INTO ringkasan_ai (id, kandidat_id, ringkasan, created_at, updated_at) VALUES ('e3ab59a0-9bb2-40a5-92a4-7b546fcf4ed0'::uuid, '39932b15-b367-4f6e-a0f4-5ae06cf0a646'::uuid, '**RINGKASAN INTI**:\nShofie Alyandra S. adalah calon siswa berprestasi akademik (bahasa) dan non-akademik (seni, hafalan 3 juz Al-Qur''an), didukung keluarga akrab, serta memiliki kemampuan adaptasi dan tanggung jawab yang baik. Meskipun secara umum sangat positif, ada sedikit perbedaan persepsi antara siswa dan orang tua pada beberapa aspek kecil.\n\n**KESELARASAN**: 85%\n**POIN UTAMA**:\n1.  Akademik & Bahasa Unggul\n2.  Religius & Seni\n3.  Mandiri & Adaptif\n4.  Dukungan Keluarga Kuat\n\n**RED FLAGS**:\n*   Perbedaan persepsi mapel sulit (BI vs Sharaf).\n*   Kemandirian sholat perlu konsistensi (menurut ortu).\n*   Penguatan keberanian dan manajemen emosi (mood swing).\n\n**REKOMENDASI SKOR**: 9/10', '2026-07-14 01:32:31.701'::timestamptz, '2026-07-14 01:32:31.701'::timestamptz) ON CONFLICT (kandidat_id) DO NOTHING;